:root {
  --ink: #070a14;
  --night: #0b1020;
  --gold: #d8b56a;
  --gold-soft: #efd9a0;
  --cream: #f4e9cf;
  --shadow: rgba(0, 0, 0, .55);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  min-height: 100%;
  background: var(--ink);
  color: var(--cream);
  overflow: hidden;
  overscroll-behavior: none;
  font-family: Verdana, "Trebuchet MS", Geneva, sans-serif;
  touch-action: manipulation;
}

body {
  background:
    radial-gradient(1100px 620px at 50% 8%, rgba(44, 68, 118, .5), transparent 68%),
    radial-gradient(900px 500px at 50% 110%, rgba(90, 54, 26, .28), transparent 70%),
    linear-gradient(180deg, #070b16 0%, #0a0f1e 52%, #05070e 100%);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .18;
  background-image:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,.5) 0 1px, transparent 1.4px),
    radial-gradient(circle at 70% 60%, rgba(255,220,160,.4) 0 1px, transparent 1.4px),
    radial-gradient(circle at 45% 85%, rgba(255,255,255,.35) 0 1px, transparent 1.4px);
  background-size: 240px 240px, 310px 310px, 190px 190px;
}

#app {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100dvh;
  width: 100vw;
  isolation: isolate;
}

#stage {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(10px, env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) 10px max(10px, env(safe-area-inset-left));
  min-height: 0;
}

#bezel {
  position: relative;
  width: min(96vw, 156dvh, 1280px);
  aspect-ratio: 960 / 600;
  border-radius: 12px;
  padding: 2px;
  background: linear-gradient(150deg, rgba(216,181,106,.85), rgba(84,69,40,.35) 24%, rgba(20,25,42,.9) 52%, rgba(216,181,106,.55));
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, .8),
    0 22px 70px rgba(0, 0, 0, .65),
    0 0 90px rgba(74, 114, 180, .16),
    inset 0 0 0 1px rgba(255, 235, 190, .15);
  overflow: hidden;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  background: #080b14;
  border-radius: 10px;
  touch-action: none;
  cursor: default;
}

#scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: 10px;
  background: repeating-linear-gradient(to bottom, rgba(255,255,255,.018) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
  opacity: .55;
}

#loading {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background: radial-gradient(circle at 50% 45%, #162036, #070a12 78%);
  color: var(--gold-soft);
  z-index: 5;
  transition: opacity .6s ease;
}
#loading.hidden { opacity: 0; pointer-events: none; }
.load-mark { font-size: 34px; color: var(--gold); animation: pulse 1.6s ease-in-out infinite; }
.load-text { font-size: 12px; letter-spacing: .22em; text-transform: uppercase; opacity: .8; }
@keyframes pulse { 0%, 100% { transform: scale(.9); opacity: .45; } 50% { transform: scale(1.15); opacity: 1; } }

#portrait-extras {
  display: none;
  text-align: center;
  padding: 6px 18px 0;
  flex: 0 0 auto;
}
.pe-brand {
  font-family: "Palatino Linotype", Palatino, Georgia, serif;
  font-size: 14px;
  letter-spacing: .4em;
  color: var(--gold-soft);
  text-indent: .4em;
}
.pe-sub {
  margin-top: 5px;
  font-size: 10px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: rgba(244, 233, 207, .45);
}

#touch {
  display: none;
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
  padding: 12px max(18px, env(safe-area-inset-left)) max(14px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-right));
  justify-content: space-between;
  align-items: flex-end;
  pointer-events: none;
  background: linear-gradient(to top, rgba(5,8,16,.82), rgba(5,8,16,.28) 62%, transparent);
}
#touch .touch-side { display: flex; align-items: flex-end; gap: 14px; pointer-events: none; }
#touch .touch-side.right { gap: 16px; }
.tbtn {
  pointer-events: auto;
  user-select: none;
  -webkit-user-select: none;
  border: 1px solid rgba(216,181,106,.42);
  background: linear-gradient(180deg, rgba(38,50,78,.92), rgba(14,19,33,.94));
  color: rgba(244,233,207,.92);
  box-shadow: 0 4px 14px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.08);
  border-radius: 12px;
  font: 600 15px/1 Verdana, sans-serif;
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  transition: transform .08s ease, background .12s ease;
  touch-action: none;
}
.tbtn:active, .tbtn.held {
  transform: scale(.93);
  background: linear-gradient(180deg, rgba(84,108,158,.95), rgba(32,44,72,.96));
  border-color: rgba(240,216,154,.8);
}
.tbtn.round { width: 66px; height: 66px; border-radius: 999px; font-size: 20px; }
.t-action { background: linear-gradient(180deg, rgba(112,84,36,.95), rgba(45,31,14,.96)); border-color: rgba(240,216,154,.65); color: #ffe9b0; }
.dpad {
  display: grid;
  grid-template-columns: repeat(3, 48px);
  grid-template-rows: repeat(3, 48px);
  gap: 2px;
  pointer-events: none;
}
.dpad .tbtn { width: 48px; height: 48px; border-radius: 10px; font-size: 13px; }
.d-up { grid-column: 2; grid-row: 1; }
.d-left { grid-column: 1; grid-row: 2; }
.d-down { grid-column: 2; grid-row: 2; }
.d-right { grid-column: 3; grid-row: 2; }

body.game-active #touch { display: flex; }
body.dialog-open #touch, body.menu-open #touch { opacity: .55; }
body.hide-touch #touch { display: none !important; }

@media (hover: none), (pointer: coarse), (max-width: 900px) {
  #bezel { width: min(98vw, 156dvh, 1280px); }
}

@media (max-width: 700px) and (orientation: portrait) {
  #stage {
    align-items: flex-start;
    padding-top: max(8px, env(safe-area-inset-top));
    padding-left: 8px;
    padding-right: 8px;
  }
  #bezel { width: 100%; border-radius: 9px; }
  #portrait-extras { display: block; margin-top: 2px; }
  #touch {
    padding-bottom: max(16px, env(safe-area-inset-bottom));
  }
  .tbtn.round { width: 64px; height: 64px; }
  .dpad { grid-template-columns: repeat(3, 50px); grid-template-rows: repeat(3, 50px); }
  .dpad .tbtn { width: 50px; height: 50px; }
}

@media (max-height: 500px) and (orientation: landscape) {
  #stage { padding-top: 4px; padding-bottom: 4px; }
  #bezel { width: min(80vw, 140dvh); }
  .tbtn { width: 44px; height: 44px; }
  .tbtn.round { width: 56px; height: 56px; }
  .dpad { grid-template-columns: repeat(3, 42px); grid-template-rows: repeat(3, 42px); }
  .dpad .tbtn { width: 42px; height: 42px; }
}

@media (prefers-reduced-motion: reduce) {
  .load-mark { animation: none; }
}

