function easeIn(t) { return t * t * t; }
function hash(n) { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); }
function rr(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.arcTo(x + w, y, x + w, y + h, rad);
  ctx.arcTo(x + w, y + h, x, y + h, rad);
  ctx.arcTo(x, y + h, x, y, rad);
  ctx.arcTo(x, y, x + w, y, rad);
  ctx.closePath();
}
function circle(ctx, x, y, r) { ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); }
function ellipse(ctx, x, y, rx, ry) { ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); }
function line(ctx, x1, y1, x2, y2, color, width = 1) {
  ctx.strokeStyle = color; ctx.lineWidth = width;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
}

function wrapLines(ctx, text, maxWidth) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let cur = '';
  for (const w of words) {
    const test = cur ? cur + ' ' + w : w;
    if (ctx.measureText(test).width > maxWidth && cur) { lines.push(cur); cur = w; }
    else cur = test;
  }
  if (cur) lines.push(cur);
  return lines;
}

function drawText(ctx, text, x, y, o = {}) {
  const size = o.size || 16;
  ctx.save();
  ctx.font = `${o.weight || ''} ${size}px ${o.font || F_BODY}`.trim();
  ctx.fillStyle = o.color || '#f4e9cf';
  ctx.textAlign = o.align || 'left';
  ctx.textBaseline = o.baseline || 'alphabetic';
  ctx.globalAlpha = o.alpha == null ? 1 : o.alpha;
  if (o.shadow) {
    ctx.shadowColor = o.shadow;
    ctx.shadowBlur = o.shadowBlur || 8;
  }
  if (o.stroke) {
    ctx.lineWidth = o.strokeWidth || 3;
    ctx.strokeStyle = o.stroke;
    ctx.lineJoin = 'round';
    ctx.strokeText(text, x, y);
  }
  ctx.fillText(text, x, y);
  ctx.restore();
}

function spacedText(ctx, text, x, y, spacing, o = {}) {
  ctx.save();
  ctx.font = `${o.weight || ''} ${o.size || 40}px ${o.font || F_SERIF}`.trim();
  ctx.textAlign = 'left'; ctx.textBaseline = o.baseline || 'alphabetic';
  ctx.fillStyle = o.color || '#e8d3a0';
  if (o.shadow) { ctx.shadowColor = o.shadow; ctx.shadowBlur = o.shadowBlur || 12; }
  let total = 0;
  for (const ch of text) total += ctx.measureText(ch).width + spacing;
  total -= spacing;
  let cx = o.align === 'center' ? x - total / 2 : o.align === 'right' ? x - total : x;
  for (const ch of text) {
    ctx.fillText(ch, cx, y);
    if (o.stroke) ctx.strokeText(ch, cx, y);
    cx += ctx.measureText(ch).width + spacing;
  }
  ctx.restore();
  return total;
}

function drawBar(ctx, x, y, w, h, pct, colA, colB, o = {}) {
  pct = clamp(pct, 0, 1);
  ctx.save();
  rr(ctx, x, y, w, h, h / 2);
  ctx.fillStyle = o.bg || 'rgba(6,9,16,.8)';
  ctx.fill();
  if (pct > 0) {
    ctx.save();
    rr(ctx, x + 1, y + 1, Math.max(1, (w - 2) * pct), h - 2, (h - 2) / 2);
    ctx.clip();
    const g = ctx.createLinearGradient(x, y, x, y + h);
    g.addColorStop(0, colA); g.addColorStop(1, colB);
    ctx.fillStyle = g; ctx.fillRect(x, y, w, h);
    ctx.fillStyle = 'rgba(255,255,255,.22)';
    ctx.fillRect(x, y + 1, w, Math.max(1, h * 0.32));
    ctx.restore();
  }
  rr(ctx, x, y, w, h, h / 2);
  ctx.strokeStyle = o.border || 'rgba(216,181,106,.35)';
  ctx.lineWidth = 1; ctx.stroke();
  ctx.restore();
}

function panel(ctx, x, y, w, h, o = {}) {
  ctx.save();
  rr(ctx, x, y, w, h, o.r == null ? 10 : o.r);
  const g = ctx.createLinearGradient(x, y, x, y + h);
  g.addColorStop(0, o.top || 'rgba(20,26,44,.94)');
  g.addColorStop(1, o.bottom || 'rgba(8,11,20,.96)');
  ctx.fillStyle = g; ctx.fill();
  ctx.lineWidth = o.borderWidth || 1.5;
  ctx.strokeStyle = o.border || 'rgba(216,181,106,.55)';
  ctx.stroke();
  if (o.inner !== false) {
    rr(ctx, x + 3.5, y + 3.5, w - 7, h - 7, Math.max(2, (o.r == null ? 10 : o.r) - 3));
    ctx.strokeStyle = o.innerColor || 'rgba(255,236,190,.13)';
    ctx.lineWidth = 1; ctx.stroke();
  }
  if (o.ornaments !== false) {
    const cs = o.corner || 'rgba(216,181,106,.75)';
    for (const [cx, cy] of [[x + 9, y + 9], [x + w - 9, y + 9], [x + 9, y + h - 9], [x + w - 9, y + h - 9]]) {
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(Math.PI / 4);
      ctx.fillStyle = cs; ctx.fillRect(-2.2, -2.2, 4.4, 4.4); ctx.restore();
    }
  }
  ctx.restore();
}

function diamond(ctx, x, y, r, color) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(Math.PI / 4);
  ctx.fillStyle = color; ctx.fillRect(-r, -r, r * 2, r * 2);
  ctx.restore();
}

function glow(ctx, x, y, r, color, alpha = 1) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = alpha;
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

function seeded(n) { return hash(n) - 0.5; }

/* ------------------------------------------------------------------ tiles */
function drawGrass(ctx, x, y, P, seed, variant) {
  const w = TILE, h = TILE;
  ctx.fillStyle = P.grass; ctx.fillRect(x, y, w, h);
  if (variant === 2) { ctx.fillStyle = 'rgba(255,255,255,.02)'; ctx.fillRect(x, y, w, h); }
  const n = 3 + Math.floor(hash(seed) * 3);
  for (let i = 0; i < n; i++) {
    const gx = x + 4 + hash(seed + i * 3.7) * (w - 8);
    const gy = y + 7 + hash(seed + i * 5.1) * (h - 12);
    ctx.strokeStyle = i % 2 ? P.tuft : P.tuftD;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(gx, gy + 3); ctx.quadraticCurveTo(gx - 1, gy, gx - 2, gy - 3);
    ctx.moveTo(gx, gy + 3); ctx.quadraticCurveTo(gx + 2, gy, gx + 3, gy - 3);
    ctx.stroke();
  }
  if (variant === 3) {
    const fx = x + 10 + hash(seed + 2) * 20, fy = y + 10 + hash(seed + 9) * 20;
    const cols = P.flower;
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2;
      ctx.fillStyle = cols[Math.floor(hash(seed + i) * cols.length)];
      circle(ctx, fx + Math.cos(a) * 2.2, fy + Math.sin(a) * 2.2, 1.7); ctx.fill();
    }
    ctx.fillStyle = '#f0d890'; circle(ctx, fx, fy, 1.3); ctx.fill();
  }
  if (variant === 4) {
    ctx.strokeStyle = P.tuftD; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x + 12, y + 30); ctx.lineTo(x + 12, y + 18);
    ctx.moveTo(x + 26, y + 32); ctx.lineTo(x + 26, y + 21); ctx.stroke();
  }
}

function drawTallGrass(ctx, x, y, P, seed) {
  drawGrass(ctx, x, y, P, seed, 1);
  ctx.save();
  ctx.strokeStyle = P.tuft; ctx.lineWidth = 1.6;
  for (let i = 0; i < 9; i++) {
    const gx = x + 3 + hash(seed + i * 2.3) * (TILE - 6);
    const gy = y + TILE - 2;
    const hgt = 13 + hash(seed + i * 7) * 15;
    ctx.strokeStyle = i % 3 === 0 ? P.tuftD : P.tuft;
    ctx.beginPath(); ctx.moveTo(gx, gy); ctx.quadraticCurveTo(gx - 3, gy - hgt * 0.6, gx - 5, gy - hgt); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(gx, gy); ctx.quadraticCurveTo(gx + 2, gy - hgt * 0.5, gx + 4, gy - hgt * 0.85); ctx.stroke();
  }
  ctx.restore();
}

function drawPath(ctx, x, y, P, seed, stoneish) {
  ctx.fillStyle = stoneish ? P.stone : P.path;
  ctx.fillRect(x, y, TILE, TILE);
  if (stoneish) {
    ctx.strokeStyle = 'rgba(0,0,0,.16)'; ctx.lineWidth = 1;
    const off = (Math.floor(x / TILE) % 2) * 10;
    ctx.beginPath();
    ctx.moveTo(x, y + 14); ctx.lineTo(x + TILE, y + 14);
    ctx.moveTo(x, y + 29); ctx.lineTo(x + TILE, y + 29);
    ctx.moveTo(x + 13 + off, y); ctx.lineTo(x + 13 + off, y + 14);
    ctx.moveTo(x + 27 - off, y + 14); ctx.lineTo(x + 27 - off, y + 29);
    ctx.moveTo(x + 8 + off, y + 29); ctx.lineTo(x + 8 + off, y + TILE);
    ctx.stroke();
  } else {
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = i % 2 ? 'rgba(255,240,200,.10)' : 'rgba(40,26,14,.12)';
      ellipse(ctx, x + 5 + hash(seed + i * 2.1) * 30, y + 6 + hash(seed + i * 4.3) * 28, 2 + hash(seed + i) * 2.4, 1.3); ctx.fill();
    }
  }
  ctx.strokeStyle = 'rgba(20,14,8,.10)'; ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, TILE - 2, TILE - 2);
}

function drawWater(ctx, x, y, P, seed, t) {
  const g = ctx.createLinearGradient(x, y, x, y + TILE);
  g.addColorStop(0, P.water); g.addColorStop(1, P.waterD);
  ctx.fillStyle = g; ctx.fillRect(x, y, TILE, TILE);
  ctx.save();
  ctx.globalAlpha = .5;
  ctx.strokeStyle = P.waterL; ctx.lineWidth = 1.4;
  const ph = (t || 0) * 1.4 + seed;
  for (let i = 0; i < 3; i++) {
    const wy = y + 9 + i * 10 + Math.sin(ph + i * 1.8) * 2;
    const wx = x + 6 + ((Math.sin(ph * .6 + i) + 1) * 6);
    ctx.beginPath(); ctx.moveTo(wx, wy);
    ctx.quadraticCurveTo(wx + 8, wy - 2, wx + 16, wy); ctx.stroke();
  }
  ctx.restore();
}

function drawBridge(ctx, x, y, P) {
  ctx.fillStyle = P.waterD; ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = '#6b4d34'; ctx.fillRect(x, y, TILE, TILE);
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = i % 2 ? '#7a583c' : '#624631';
    ctx.fillRect(x, y + i * 8, TILE, 7);
    ctx.fillStyle = 'rgba(20,12,6,.25)'; ctx.fillRect(x, y + i * 8 + 7, TILE, 1);
  }
  ctx.fillStyle = '#8f6a46'; ctx.fillRect(x, y, 3, TILE); ctx.fillRect(x + TILE - 3, y, 3, TILE);
  ctx.fillStyle = 'rgba(255,220,160,.07)'; ctx.fillRect(x + 3, y, 4, TILE);
}

function drawTree(ctx, x, y, P, seed) {
  drawGrass(ctx, x, y, P, seed, 0);
  ctx.save();
  ctx.fillStyle = 'rgba(10,16,12,.24)';
  ellipse(ctx, x + 20, y + 34, 16, 5); ctx.fill();
  ctx.fillStyle = P.trunk;
  ctx.fillRect(x + 17, y + 20, 6, 16);
  ctx.fillStyle = P.treeD;
  circle(ctx, x + 19, y + 13, 17); ctx.fill();
  ctx.fillStyle = P.tree;
  circle(ctx, x + 15, y + 10, 13); ctx.fill();
  circle(ctx, x + 26, y + 12, 12); ctx.fill();
  circle(ctx, x + 20, y + 20, 12); ctx.fill();
  ctx.fillStyle = P.treeL;
  circle(ctx, x + 14, y + 7, 7); ctx.fill();
  circle(ctx, x + 24, y + 6, 5.5); ctx.fill();
  circle(ctx, x + 26, y + 17, 5); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,220,.08)';
  circle(ctx, x + 11, y + 4, 4); ctx.fill();
  ctx.restore();
}

function drawBush(ctx, x, y, P, seed) {
  drawGrass(ctx, x, y, P, seed, 0);
  ctx.fillStyle = 'rgba(10,16,12,.2)'; ellipse(ctx, x + 20, y + 31, 13, 4); ctx.fill();
  ctx.fillStyle = P.treeD; circle(ctx, x + 14, y + 25, 9); ctx.fill(); circle(ctx, x + 26, y + 26, 8); ctx.fill();
  ctx.fillStyle = P.tree; circle(ctx, x + 20, y + 23, 10); ctx.fill(); circle(ctx, x + 27, y + 20, 6); ctx.fill();
  ctx.fillStyle = P.treeL; circle(ctx, x + 16, y + 19, 5); ctx.fill();
}

function drawHouseWall(ctx, x, y, P, seed, door) {
  ctx.fillStyle = P.wall; ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = 'rgba(0,0,0,.12)'; ctx.fillRect(x, y + TILE - 5, TILE, 5);
  // vigas de madeira
  ctx.fillStyle = P.timber;
  ctx.fillRect(x, y, 3, TILE); ctx.fillRect(x + TILE - 3, y, 3, TILE);
  ctx.fillRect(x, y + 3, TILE, 3);
  ctx.fillRect(x, y + TILE - 6, TILE, 3);
  if (door) {
    ctx.fillStyle = '#3a2618'; ctx.fillRect(x + 7, y + 8, 26, 30);
    ctx.fillStyle = '#5b3a22'; ctx.fillRect(x + 9, y + 10, 22, 28);
    ctx.fillStyle = 'rgba(255,220,150,.5)';
    ctx.fillRect(x + 12, y + 13, 16, 10);
    ctx.fillStyle = '#7c5a34'; ctx.fillRect(x + 19, y + 10, 2, 27);
    ctx.strokeStyle = 'rgba(20,10,4,.4)'; ctx.strokeRect(x + 9, y + 10, 22, 28);
    ctx.fillStyle = '#d8b56a'; circle(ctx, x + 27, y + 25, 1.6); ctx.fill();
  } else {
    // janela
    ctx.fillStyle = 'rgba(20,14,8,.65)'; ctx.fillRect(x + 10, y + 12, 20, 15);
    ctx.fillStyle = '#f2c977'; ctx.fillRect(x + 12, y + 14, 16, 11);
    ctx.fillStyle = 'rgba(255,255,220,.5)'; ctx.fillRect(x + 13, y + 15, 6, 4);
    ctx.fillStyle = P.timber; ctx.fillRect(x + 19, y + 12, 2, 15); ctx.fillRect(x + 10, y + 18, 20, 2);
    ctx.fillStyle = 'rgba(10,6,2,.35)'; ctx.fillRect(x + 8, y + 27, 24, 2);
  }
}

function drawRoof(ctx, x, y, P, seed) {
  ctx.fillStyle = P.roofD; ctx.fillRect(x, y, TILE, TILE);
  for (let row = 0; row < 4; row++) {
    const oy = y + row * 10;
    for (let col = -1; col < 4; col++) {
      const ox = x + col * 14 + (row % 2 ? 7 : 0);
      ctx.fillStyle = (row + col) % 2 ? P.roof : P.roofL;
      ctx.beginPath();
      ctx.moveTo(ox, oy + 1); ctx.lineTo(ox + 14, oy + 1); ctx.lineTo(ox + 14, oy + 7);
      ctx.quadraticCurveTo(ox + 7, oy + 12, ox, oy + 7); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(20,8,6,.3)'; ctx.lineWidth = 1; ctx.stroke();
    }
  }
  ctx.fillStyle = 'rgba(255,220,180,.08)'; ctx.fillRect(x, y, TILE, 4);
}

function drawFountainTile(ctx, x, y, P, seed) {
  ctx.fillStyle = P.stone; ctx.fillRect(x, y, TILE, TILE);
  ctx.strokeStyle = 'rgba(30,30,30,.22)'; ctx.strokeRect(x + 2, y + 2, TILE - 4, TILE - 4);
  ctx.fillStyle = P.waterD; ctx.fillRect(x + 4, y + 4, TILE - 8, TILE - 8);
  ctx.fillStyle = 'rgba(140,200,220,.18)'; ctx.fillRect(x + 6, y + 6, TILE - 12, 4);
}

function drawWall(ctx, x, y, P, seed, kind) {
  const big = kind === 'castle' || kind === 'prison';
  ctx.fillStyle = P.wall; ctx.fillRect(x, y, TILE, TILE);
  ctx.strokeStyle = 'rgba(0,0,0,.28)'; ctx.lineWidth = 1.4;
  const bh = big ? 20 : 13;
  for (let row = 0; row < 2; row++) {
    const oy = y + row * bh;
    const off = row % 2 ? 10 : 0;
    ctx.strokeRect(x, oy, TILE, bh);
    ctx.beginPath(); ctx.moveTo(x + 20 + off, oy); ctx.lineTo(x + 20 + off, oy + bh); ctx.stroke();
  }
  ctx.fillStyle = 'rgba(255,255,255,.04)'; ctx.fillRect(x, y, TILE, 3);
  ctx.fillStyle = 'rgba(0,0,0,.18)'; ctx.fillRect(x, y + TILE - 4, TILE, 4);
  ctx.fillStyle = 'rgba(70,100,60,.15)';
  ellipse(ctx, x + 9 + hash(seed) * 20, y + 12 + hash(seed + 2) * 16, 6, 3); ctx.fill();
  if (kind === 'prison') {
    ctx.fillStyle = 'rgba(10,12,16,.22)'; ctx.fillRect(x + 12, y + 34, 3, 6);
  }
}

function drawBars(ctx, x, y, P) {
  ctx.fillStyle = P.stoneD; ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = 'rgba(0,0,0,.35)'; ctx.fillRect(x, y + 8, TILE, 24);
  ctx.fillStyle = 'rgba(30,34,40,.9)'; ctx.fillRect(x, y, TILE, 8);
  for (let i = 0; i < 5; i++) {
    const bx = x + 4 + i * 8;
    ctx.fillStyle = '#7a818c'; ctx.fillRect(bx, y, 3, TILE);
    ctx.fillStyle = 'rgba(220,230,240,.35)'; ctx.fillRect(bx, y, 1, TILE);
    ctx.fillStyle = '#3b4048'; ctx.fillRect(bx + 2, y, 1, TILE);
  }
  ctx.fillStyle = '#59616c'; ctx.fillRect(x, y + 13, TILE, 3);
  ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.fillRect(x, y + 13, TILE, 1);
}

function drawStoneFloor(ctx, x, y, P, seed) {
  ctx.fillStyle = P.stone; ctx.fillRect(x, y, TILE, TILE);
  ctx.strokeStyle = 'rgba(0,0,0,.24)'; ctx.lineWidth = 1;
  const off = (Math.floor(x / TILE) + Math.floor(y / TILE)) % 2 ? 10 : 0;
  ctx.beginPath();
  ctx.moveTo(x + 20 + off, y); ctx.lineTo(x + 20 + off, y + 20);
  ctx.moveTo(x, y + 20); ctx.lineTo(x + 20 + off, y + 20);
  ctx.moveTo(x + 20 + off, y + 20); ctx.lineTo(x + 20 + off, y + TILE);
  ctx.moveTo(x + 20 + off, y + 20); ctx.lineTo(x + TILE, y + 20);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,.035)';
  ellipse(ctx, x + 10 + hash(seed) * 18, y + 8 + hash(seed + 1) * 22, 5, 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,.10)';
  ellipse(ctx, x + 25 + hash(seed + 5) * 12, y + 24 + hash(seed + 4) * 12, 3, 1.4); ctx.fill();
}

function drawCarpet(ctx, x, y, P) {
  ctx.fillStyle = P.stone; ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = P.rug; ctx.fillRect(x, y, TILE, TILE);
  ctx.fillStyle = 'rgba(0,0,0,.12)';
  for (let i = 0; i < 4; i++) ctx.fillRect(x, y + i * 11, TILE, 1);
  ctx.fillStyle = P.gold || '#d8b56a';
  ctx.globalAlpha = .5;
  if (x % 80 === 0) ctx.fillRect(x + 2, y, 2, TILE);
  if ((x + TILE) % 80 === 0) ctx.fillRect(x + TILE - 4, y, 2, TILE);
  ctx.globalAlpha = 1;
  ctx.fillStyle = 'rgba(255,230,180,.06)'; ctx.fillRect(x, y, TILE, 4);
}

function drawVoid(ctx, x, y, P, seed) {
  const g = ctx.createLinearGradient(x, y, x, y + TILE);
  g.addColorStop(0, '#0a0f1d'); g.addColorStop(1, '#0d1426');
  ctx.fillStyle = g; ctx.fillRect(x, y, TILE, TILE);
  for (let i = 0; i < 3; i++) {
    const sx = x + hash(seed + i * 3.3) * TILE;
    const sy = y + hash(seed + i * 7.7) * TILE;
    ctx.fillStyle = `rgba(200,220,255,${.16 + hash(seed + i) * .4})`;
    ctx.fillRect(sx, sy, 1.4, 1.4);
  }
  const nx = x + hash(seed + 11) * TILE, ny = y + hash(seed + 13) * TILE;
  if (hash(seed + 17) > .72) {
    const rg = ctx.createRadialGradient(nx, ny, 0, nx, ny, 12);
    rg.addColorStop(0, 'rgba(120,150,220,.20)'); rg.addColorStop(1, 'rgba(120,150,220,0)');
    ctx.fillStyle = rg; ctx.fillRect(x, y, TILE, TILE);
  }
}

function drawRune(ctx, x, y, P, seed, t) {
  drawStoneFloor(ctx, x, y, P, seed);
  const cx = x + 20, cy = y + 20;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, 0, 22, 'rgba(120,220,255,.28)', .8);
  ctx.strokeStyle = 'rgba(150,230,255,.75)'; ctx.lineWidth = 1.6;
  circle(ctx, 0, 0, 13); ctx.stroke();
  ctx.rotate((t || 0) * .2 + seed);
  ctx.strokeStyle = 'rgba(190,240,255,.55)'; ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(0, 0, 9, i * 2.1, i * 2.1 + .9); ctx.stroke();
  }
  ctx.fillStyle = 'rgba(180,240,255,.7)';
  for (let i = 0; i < 4; i++) { const a = i * Math.PI / 2 + .5; ctx.fillRect(Math.cos(a) * 13 - 1, Math.sin(a) * 13 - 1, 2, 2); }
  ctx.restore();
}

function drawCrystal(ctx, x, y, P, seed, t) {
  drawStoneFloor(ctx, x, y, P, seed);
  ctx.save(); ctx.translate(x + 20, y + 32);
  glow(ctx, 0, -12, 22, 'rgba(120,220,255,.24)', .8);
  ctx.fillStyle = 'rgba(140,220,240,.8)';
  ctx.beginPath(); ctx.moveTo(0, -32); ctx.lineTo(9, -8); ctx.lineTo(4, 4); ctx.lineTo(-5, 3); ctx.lineTo(-9, -9); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(220,255,255,.45)';
  ctx.beginPath(); ctx.moveTo(0, -30); ctx.lineTo(3, -8); ctx.lineTo(0, 2); ctx.lineTo(-3, -8); ctx.closePath(); ctx.fill();
  ctx.restore();
}

function drawPillar(ctx, x, y, P, seed) {
  drawStoneFloor(ctx, x, y, P, seed);
  ctx.fillStyle = 'rgba(0,0,0,.28)'; ctx.fillRect(x + 4, y + 33, 32, 7);
  ctx.fillStyle = P.stoneD; ctx.fillRect(x + 8, y + 6, 24, 28);
  ctx.fillStyle = P.stoneL; ctx.fillRect(x + 10, y + 6, 6, 28);
  ctx.fillStyle = P.stone; ctx.fillRect(x + 16, y + 6, 14, 28);
  ctx.fillStyle = 'rgba(0,0,0,.25)'; ctx.fillRect(x + 28, y + 6, 4, 28);
  ctx.fillStyle = P.stoneL; ctx.fillRect(x + 5, y + 2, 30, 7); ctx.fillRect(x + 5, y + 32, 30, 6);
  ctx.strokeStyle = 'rgba(0,0,0,.25)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x + 16, y + 10); ctx.lineTo(x + 16, y + 32); ctx.stroke();
}

function drawAltar(ctx, x, y, P, seed) {
  drawStoneFloor(ctx, x, y, P, seed);
  ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.fillRect(x + 5, y + 33, 30, 6);
  ctx.fillStyle = '#2e3340'; ctx.fillRect(x + 7, y + 12, 26, 22);
  ctx.fillStyle = '#454e60'; ctx.fillRect(x + 9, y + 12, 22, 7);
  ctx.fillStyle = P.gold || '#d8b56a'; ctx.fillRect(x + 9, y + 18, 22, 2);
  ctx.fillStyle = 'rgba(140,220,255,.6)'; ctx.fillRect(x + 12, y + 9, 16, 3);
  glow(ctx, x + 20, y + 10, 16, 'rgba(140,220,255,.3)', .7);
}

function drawGate(ctx, x, y, P, theme) {
  if (theme === 'prison') {
    // escada para cima
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = i % 2 ? '#4a4d53' : '#3a3d42';
      ctx.fillRect(x + 4, y + 34 - i * 7, 32, 8);
      ctx.fillStyle = 'rgba(255,255,255,.08)'; ctx.fillRect(x + 4, y + 34 - i * 7, 32, 1);
    }
    ctx.fillStyle = 'rgba(0,0,0,.4)'; ctx.fillRect(x + 10, y + 2, 20, 10);
    glow(ctx, x + 20, y + 8, 16, 'rgba(255,210,140,.12)', .7);
  } else {
    ctx.fillStyle = '#2b2324'; ctx.fillRect(x, y, TILE, TILE);
    ctx.fillStyle = '#3d3030'; ctx.fillRect(x + 4, y + 4, 32, 36);
    ctx.fillStyle = '#211a1a';
    ctx.beginPath(); ctx.moveTo(x + 8, y + 40); ctx.lineTo(x + 8, y + 18); ctx.quadraticCurveTo(x + 20, y + 2, x + 32, y + 18); ctx.lineTo(x + 32, y + 40); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = P.gold; ctx.lineWidth = 2; ctx.stroke();
    ctx.strokeStyle = 'rgba(200,180,120,.28)'; ctx.lineWidth = 1;
    for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(x + 10 + i * 5, y + 12); ctx.lineTo(x + 10 + i * 5, y + 40); ctx.stroke(); }
  }
}

function drawFence(ctx, x, y, P) {
  drawGrass(ctx, x, y, P, x + y, 0);
  ctx.fillStyle = '#6a5138';
  ctx.fillRect(x + 4, y + 18, 4, 18); ctx.fillRect(x + 18, y + 18, 4, 18); ctx.fillRect(x + 32, y + 18, 4, 18);
  ctx.fillRect(x, y + 22, TILE, 3); ctx.fillRect(x, y + 31, TILE, 3);
  ctx.fillStyle = 'rgba(255,240,200,.12)'; ctx.fillRect(x, y + 22, TILE, 1);
}

/* ------------------------------------------------------- static map baking */
function drawTile(ctx, ch, x, y, theme, t) {
  const P = PALETTES[theme] || PALETTES.village;
  const seed = x * 13.37 + y * 7.77;
  const variant = Math.floor(hash(seed) * 5);
  switch (ch) {
    case '.': drawGrass(ctx, x, y, P, seed, 0); break;
    case ',': drawGrass(ctx, x, y, P, seed, 3); break;
    case ':': drawTallGrass(ctx, x, y, P, seed); break;
    case 'p': drawPath(ctx, x, y, P, seed, false); break;
    case 'P': drawPath(ctx, x, y, P, seed, true); break;
    case 's': drawStoneFloor(ctx, x, y, P, seed); break;
    case 'c': drawCarpet(ctx, x, y, P); break;
    case 'w': drawWater(ctx, x, y, P, seed, t); break;
    case 'b': drawBridge(ctx, x, y, P); break;
    case 'T': drawTree(ctx, x, y, P, seed); break;
    case 't': drawBush(ctx, x, y, P, seed); break;
    case 'H': drawHouseWall(ctx, x, y, P, seed, false); break;
    case 'D': drawHouseWall(ctx, x, y, P, seed, true); break;
    case 'R': drawRoof(ctx, x, y, P, seed); break;
    case 'F': drawFence(ctx, x, y, P); break;
    case 'f': drawFountainTile(ctx, x, y, P, seed); break;
    case 'S': drawWall(ctx, x, y, P, seed, 'stone'); break;
    case 'W': drawWall(ctx, x, y, P, seed, theme === 'prison' ? 'prison' : 'castle'); break;
    case '|': drawBars(ctx, x, y, P); break;
    case '#': drawVoid(ctx, x, y, P, seed); break;
    case '*': drawRune(ctx, x, y, P, seed, t); break;
    case 'C': drawCrystal(ctx, x, y, P, seed, t); break;
    case 'o': drawPillar(ctx, x, y, P, seed); break;
    case 'A': drawAltar(ctx, x, y, P, seed); break;
    case 'G': drawGate(ctx, x, y, P, theme); break;
    case 'M': drawPath(ctx, x, y, P, seed, true); break;
    default: drawGrass(ctx, x, y, P, seed, 0);
  }
}

function bakeMap(map, theme) {
  const c = document.createElement('canvas');
  c.width = MAP_W * TILE; c.height = MAP_H * TILE;
  const ctx = c.getContext('2d');
  for (let y = 0; y < MAP_H; y++) {
    for (let x = 0; x < MAP_W; x++) {
      drawTile(ctx, map.grid[y][x], x * TILE, y * TILE, theme, 0);
    }
  }
  // sombra nas bordas das casas e muros
  for (let y = 0; y < MAP_H; y++) {
    for (let x = 0; x < MAP_W; x++) {
      const ch = map.grid[y][x];
      if (ch === 'R' || ch === 'H' || ch === 'W' || ch === 'S' || ch === 'T') {
        const below = map.grid[y + 1] && map.grid[y + 1][x];
        if (below && !'RHWST|'.includes(below)) {
          ctx.fillStyle = 'rgba(4,8,12,.28)';
          ctx.fillRect(x * TILE, (y + 1) * TILE - 4, TILE, 5);
        }
      }
    }
  }
  return c;
}

/* ------------------------------------------------------- landmarks/props */
function drawFountainLandmark(ctx, lx, ly, t) {
  const cx = lx + 80, cy = ly + 40;
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,.28)'; ellipse(ctx, cx, cy + 30, 80, 18); ctx.fill();
  // base
  ctx.fillStyle = '#6f6c5f'; ellipse(ctx, cx, cy + 8, 74, 34); ctx.fill();
  ctx.fillStyle = '#8b8875'; ellipse(ctx, cx, cy + 2, 74, 34); ctx.fill();
  ctx.fillStyle = '#a5a18a'; ellipse(ctx, cx, cy - 2, 66, 29); ctx.fill();
  ctx.fillStyle = '#3a6a84'; ellipse(ctx, cx, cy - 2, 58, 24); ctx.fill();
  // água
  for (let i = 0; i < 4; i++) {
    ctx.strokeStyle = `rgba(160,215,230,${.18 + .1 * Math.sin(t * 1.5 + i)})`;
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.ellipse(cx, cy - 2, 20 + i * 11, 8 + i * 4.5, 0, 0, Math.PI * 2); ctx.stroke();
  }
  // coluna e estátua
  ctx.fillStyle = '#8b8875'; ctx.fillRect(cx - 7, cy - 42, 14, 40);
  ctx.fillStyle = '#a5a18a'; ctx.fillRect(cx - 5, cy - 42, 4, 40);
  ctx.fillStyle = '#b8b49c';
  circle(ctx, cx, cy - 52, 8); ctx.fill();
  ctx.fillRect(cx - 6, cy - 48, 12, 10);
  // jarro
  ctx.fillStyle = '#9a9680';
  ctx.beginPath(); ctx.moveTo(cx - 12, cy - 62); ctx.quadraticCurveTo(cx, cy - 72, cx + 12, cy - 62); ctx.lineTo(cx + 7, cy - 50); ctx.lineTo(cx - 7, cy - 50); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(180,230,240,.5)'; ctx.lineWidth = 1.6;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath(); ctx.moveTo(cx + i * 6, cy - 50 + Math.sin(t * 2 + i) * 1.5);
    ctx.quadraticCurveTo(cx + i * 9, cy - 30, cx + i * 7, cy - 10); ctx.stroke();
  }
  // brilho
  glow(ctx, cx, cy - 2, 55, 'rgba(120,200,220,.15)', .8);
  ctx.restore();
}

function drawThroneLandmark(ctx, x, y) {
  const cx = x + 40, base = y + 70;
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,.35)'; ellipse(ctx, cx, base, 46, 12); ctx.fill();
  ctx.fillStyle = '#4a3d2c'; ctx.fillRect(cx - 32, base - 60, 64, 60);
  ctx.fillStyle = '#6b5738'; ctx.fillRect(cx - 26, base - 56, 52, 52);
  ctx.fillStyle = '#8c2c38'; ctx.fillRect(cx - 20, base - 66, 40, 58);
  ctx.fillStyle = '#a8404c'; ctx.fillRect(cx - 16, base - 62, 32, 38);
  ctx.fillStyle = '#d8b56a'; ctx.fillRect(cx - 22, base - 8, 44, 5);
  ctx.fillStyle = '#d8b56a'; ctx.fillRect(cx - 30, base - 70, 60, 6);
  for (let i = 0; i < 5; i++) diamond(ctx, cx - 24 + i * 12, base - 72, 3.2, '#e8cf90');
  ctx.restore();
}

function drawChest(ctx, x, y, open, t) {
  ctx.save();
  const bob = open ? 0 : Math.sin((t || 0) * 2.2 + x) * 0.6;
  ctx.translate(x, y + bob);
  ctx.fillStyle = 'rgba(0,0,0,.3)'; ellipse(ctx, 0, 2, 15, 4.5); ctx.fill();
  ctx.fillStyle = '#5e3d24'; rr(ctx, -14, -19, 28, 20, 3); ctx.fill();
  ctx.fillStyle = '#7a5230'; rr(ctx, -13, -18, 26, 18, 2); ctx.fill();
  if (open) {
    ctx.fillStyle = '#2a1c12'; ctx.fillRect(-12, -18, 24, 8);
    ctx.fillStyle = '#8a6238'; rr(ctx, -15, -30, 30, 12, 4); ctx.fill();
    ctx.fillStyle = 'rgba(240,210,140,.18)'; glow(ctx, 0, -14, 24, 'rgba(255,220,150,.3)', .7);
  } else {
    ctx.fillStyle = '#8a6238'; rr(ctx, -15, -30, 30, 14, 5); ctx.fill();
    ctx.fillStyle = 'rgba(255,230,170,.14)'; ctx.fillRect(-12, -28, 8, 3);
  }
  ctx.fillStyle = '#d8b56a'; ctx.fillRect(-15, -19, 30, 3);
  ctx.fillStyle = '#e8cf90'; ctx.fillRect(-2, -21, 4, 7);
  ctx.fillStyle = '#3a2818'; ctx.fillRect(-1, -19, 2, 3);
  ctx.strokeStyle = 'rgba(30,18,8,.5)'; ctx.lineWidth = 1; rr(ctx, -14, -19, 28, 20, 3); ctx.stroke();
  ctx.restore();
}

function drawFlower(ctx, x, y, t) {
  ctx.save();
  ctx.translate(x, y);
  const bob = Math.sin((t || 0) * 2) * 1.2;
  glow(ctx, 0, -10 + bob, 26, 'rgba(240,220,150,.22)', .8);
  ctx.strokeStyle = '#4f7a4a'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, 4); ctx.quadraticCurveTo(-2, -6, 0, -14 + bob); ctx.stroke();
  ctx.fillStyle = '#5f8a52';
  ellipse(ctx, -6, -2, 5, 2.4); ctx.fill();
  // pétalas
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3 + Math.sin(t * .8) * .1;
    ctx.fillStyle = i % 2 ? '#f2e2a0' : '#e8c878';
    ellipse(ctx, Math.cos(a) * 6, -16 + bob + Math.sin(a) * 6, 4.2, 2.6); ctx.fill();
  }
  ctx.fillStyle = '#fff6d0'; circle(ctx, 0, -16 + bob, 2.6); ctx.fill();
  ctx.fillStyle = 'rgba(240,220,150,.8)';
  for (let i = 0; i < 3; i++) {
    const a = t * 1.4 + i * 2.1;
    ctx.globalAlpha = .3 + .5 * (Math.sin(t * 3 + i) * .5 + .5);
    ctx.fillRect(Math.cos(a) * (10 + i * 4), -16 + Math.sin(a) * (8 + i * 2), 1.6, 1.6);
  }
  ctx.restore();
}

function drawSparkle(ctx, x, y, t, color = 'rgba(255,235,170,') {
  for (let i = 0; i < 3; i++) {
    const a = (t * .7 + i * 2.1) % (Math.PI * 2);
    const r = 8 + i * 3;
    ctx.fillStyle = color + (0.35 + 0.4 * Math.sin(t * 2.5 + i)) + ')';
    ctx.fillRect(x + Math.cos(a) * r, y + Math.sin(a) * r, 2, 2);
  }
}

function drawSignpost(ctx, x, y) {
  ctx.fillStyle = 'rgba(0,0,0,.25)'; ellipse(ctx, x, y + 2, 10, 3); ctx.fill();
  ctx.fillStyle = '#5c4128'; ctx.fillRect(x - 2, y - 26, 4, 28);
  ctx.fillStyle = '#8a6a43'; ctx.fillRect(x - 13, y - 28, 26, 12);
  ctx.fillStyle = '#6b4e30'; ctx.fillRect(x - 13, y - 28, 26, 2);
  ctx.fillStyle = 'rgba(255,235,190,.35)'; ctx.fillRect(x - 9, y - 24, 14, 1);
}

/* --------------------------------------------------------------- portraits */
function drawPortrait(ctx, who, mood, x, y, w, h) {
  const look = LOOKS[who] || LOOKS.rowan;
  const palettes = {
    rowan: ['#2b3d5e', '#7a9ac0'], liria: ['#4b3348', '#c98aa8'], liria_ruins: ['#3a2d40', '#9a7a90'],
    kael: ['#4b2626', '#c09050'], brann: ['#323a46', '#b0a890'], king: ['#3a2d4a', '#b8a070'],
    guard: ['#2b3038', '#8a96a4'], elder: ['#3a3446', '#a09070'], child: ['#33452f', '#a8c090'],
    merchant: ['#453425', '#c0a070'], noble: ['#2f3a50', '#a0a8c0'], noble2: ['#3a2b34', '#b090a0']
  };
  const pal = palettes[who] || palettes.rowan;
  const bo = mood === 'angry' || mood === 'smirk' ? 'angry' : mood === 'sad' || mood === 'tears' ? 'sad' : 'neutral';
  ctx.save();
  ctx.beginPath(); ctx.rect(x, y, w, h); ctx.clip();
  const bg = ctx.createRadialGradient(x + w * .5, y + h * .36, 6, x + w * .5, y + h * .5, w * .85);
  bg.addColorStop(0, pal[0]);
  bg.addColorStop(1, '#0c101c');
  ctx.fillStyle = bg; ctx.fillRect(x, y, w, h);
  // textura
  ctx.globalAlpha = .12;
  for (let i = 0; i < 18; i++) {
    ctx.fillStyle = i % 2 ? '#ffffff' : '#000000';
    ctx.fillRect(x + hash(i * 3.7) * w, y + hash(i * 5.1) * h, 1, 1);
  }
  ctx.globalAlpha = 1;
  // halo
  const hg = ctx.createRadialGradient(x + w * .52, y + h * .34, 4, x + w * .52, y + h * .34, w * .5);
  hg.addColorStop(0, 'rgba(255,235,190,.18)'); hg.addColorStop(1, 'rgba(255,235,190,0)');
  ctx.fillStyle = hg; ctx.fillRect(x, y, w, h);

  const sx = w / 100, sy = h / 120;
  ctx.translate(x, y); ctx.scale(sx, sy);
  const skin = look.skin, hair = look.hair;
  const hairStyle = look.style;

  // ombros / roupa
  ctx.fillStyle = look.cape || look.top;
  ctx.beginPath();
  ctx.moveTo(5, 120); ctx.quadraticCurveTo(9, 92, 32, 82);
  ctx.lineTo(68, 82); ctx.quadraticCurveTo(91, 92, 95, 120); ctx.closePath(); ctx.fill();
  ctx.fillStyle = look.top;
  ctx.beginPath();
  ctx.moveTo(15, 120); ctx.quadraticCurveTo(20, 96, 38, 88);
  ctx.lineTo(62, 88); ctx.quadraticCurveTo(80, 96, 85, 120); ctx.closePath(); ctx.fill();
  // gola
  ctx.fillStyle = look.accent;
  ctx.beginPath(); ctx.moveTo(38, 88); ctx.lineTo(50, 100); ctx.lineTo(62, 88); ctx.lineTo(56, 85); ctx.lineTo(50, 92); ctx.lineTo(44, 85); ctx.closePath(); ctx.fill();
  // pescoço
  ctx.fillStyle = skin;
  ctx.fillRect(44, 78, 12, 14);
  ctx.fillStyle = 'rgba(60,30,20,.18)'; ctx.fillRect(44, 86, 12, 6);

  // cabelo comprido atrás
  if (hairStyle === 'long') {
    ctx.fillStyle = hair;
    ctx.beginPath(); ctx.moveTo(28, 48); ctx.quadraticCurveTo(20, 74, 24, 96);
    ctx.quadraticCurveTo(34, 100, 34, 82); ctx.lineTo(39, 48); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(72, 48); ctx.quadraticCurveTo(80, 74, 76, 96);
    ctx.quadraticCurveTo(66, 100, 66, 82); ctx.lineTo(61, 48); ctx.closePath(); ctx.fill();
  }
  // cabeça
  ctx.fillStyle = skin;
  ellipse(ctx, 50, 58, 20, 24); ctx.fill();
  ctx.fillStyle = 'rgba(80,40,20,.10)';
  ellipse(ctx, 50, 69, 16, 10); ctx.fill();
  // orelhas
  ctx.fillStyle = skin;
  ellipse(ctx, 29, 60, 4, 6); ctx.fill();
  ellipse(ctx, 71, 60, 4, 6); ctx.fill();
  ctx.fillStyle = 'rgba(80,40,20,.25)';
  ctx.fillRect(30, 59, 1.6, 3); ctx.fillRect(69, 59, 1.6, 3);
  // cabelo
  ctx.fillStyle = hair;
  if (hairStyle === 'helmet') {
    ctx.fillStyle = '#6a727e';
    ctx.beginPath(); ctx.moveTo(28, 54); ctx.quadraticCurveTo(30, 26, 50, 26); ctx.quadraticCurveTo(70, 26, 72, 54);
    ctx.lineTo(68, 48); ctx.quadraticCurveTo(64, 36, 50, 34); ctx.quadraticCurveTo(36, 36, 32, 48); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#4a525c'; ctx.fillRect(48, 34, 4, 22);
    ctx.fillStyle = '#a8b0ba'; ctx.fillRect(28, 44, 44, 3);
  } else {
    ctx.beginPath();
    ctx.moveTo(28, 58); ctx.quadraticCurveTo(26, 30, 50, 28); ctx.quadraticCurveTo(74, 30, 72, 58);
    ctx.quadraticCurveTo(66, 44, 54, 42); ctx.quadraticCurveTo(48, 50, 40, 44);
    ctx.quadraticCurveTo(34, 48, 32, 60); ctx.closePath(); ctx.fill();
    if (hairStyle === 'hero' || hairStyle === 'short' || hairStyle === 'beard') {
      ctx.beginPath(); ctx.moveTo(30, 50); ctx.quadraticCurveTo(26, 66, 33, 78); ctx.lineTo(38, 72);
      ctx.quadraticCurveTo(34, 60, 38, 46); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(70, 50); ctx.quadraticCurveTo(74, 66, 67, 78); ctx.lineTo(62, 72);
      ctx.quadraticCurveTo(66, 60, 62, 46); ctx.closePath(); ctx.fill();
    }
    // franja
    ctx.beginPath(); ctx.moveTo(32, 46); ctx.quadraticCurveTo(38, 32, 52, 34);
    ctx.quadraticCurveTo(60, 35, 67, 47); ctx.quadraticCurveTo(58, 44, 52, 38);
    ctx.quadraticCurveTo(44, 44, 36, 48); ctx.closePath(); ctx.fill();
  }
  if (hairStyle === 'beard') {
    ctx.fillStyle = hair;
    ctx.beginPath(); ctx.moveTo(34, 68); ctx.quadraticCurveTo(38, 96, 50, 98);
    ctx.quadraticCurveTo(62, 96, 66, 68); ctx.quadraticCurveTo(58, 82, 50, 82);
    ctx.quadraticCurveTo(42, 82, 34, 68); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.28)';
    ctx.fillRect(46, 84, 2, 6); ctx.fillRect(52, 86, 2, 4);
  }
  if (look.flower) {
    ctx.fillStyle = '#e8c878';
    for (let i = 0; i < 5; i++) { const a = i * Math.PI * 2 / 5; circle(ctx, 66 + Math.cos(a) * 3, 40 + Math.sin(a) * 3, 2); ctx.fill(); }
    ctx.fillStyle = '#f8e8b0'; circle(ctx, 66, 40, 1.8); ctx.fill();
  }
  if (look.crown) {
    ctx.fillStyle = '#e0bd72';
    ctx.beginPath(); ctx.moveTo(34, 32); ctx.lineTo(38, 20); ctx.lineTo(44, 29); ctx.lineTo(50, 17);
    ctx.lineTo(56, 29); ctx.lineTo(62, 20); ctx.lineTo(66, 32); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#b08a3e'; ctx.fillRect(34, 30, 32, 4);
    ctx.fillStyle = '#c94b4b'; circle(ctx, 50, 32, 2); ctx.fill();
  }
  // olhos
  const eyeY = 59;
  const iris = who === 'liria' || who === 'liria_ruins' ? '#5a8a5a' : who === 'kael' ? '#c08a3a' : who === 'brann' ? '#6a7a8a' : who === 'guard' ? '#7a8a9a' : '#4a7a9a';
  if (mood !== 'pained') {
    ctx.fillStyle = '#f8f2e4';
    ellipse(ctx, 41, eyeY, 5, bo === 'angry' ? 2.6 : 3.6); ctx.fill();
    ellipse(ctx, 59, eyeY, 5, bo === 'angry' ? 2.6 : 3.6); ctx.fill();
    ctx.fillStyle = iris;
    circle(ctx, 41.5, eyeY + .5, 2.3); ctx.fill();
    circle(ctx, 58.5, eyeY + .5, 2.3); ctx.fill();
    ctx.fillStyle = '#1a1410';
    circle(ctx, 41.5, eyeY + .5, 1.2); ctx.fill();
    circle(ctx, 58.5, eyeY + .5, 1.2); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.85)';
    ctx.fillRect(40, eyeY - 1.4, 1.2, 1.2); ctx.fillRect(57, eyeY - 1.4, 1.2, 1.2);
    // pálpebra
    ctx.strokeStyle = 'rgba(50,30,24,.6)'; ctx.lineWidth = .8;
    ctx.beginPath(); ctx.moveTo(36, eyeY - 2.6); ctx.lineTo(46, eyeY - 2.6); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(54, eyeY - 2.6); ctx.lineTo(64, eyeY - 2.6); ctx.stroke();
  } else {
    ctx.strokeStyle = 'rgba(40,28,24,.75)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(36, 59); ctx.quadraticCurveTo(41, 61, 46, 59); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(54, 59); ctx.quadraticCurveTo(59, 61, 64, 59); ctx.stroke();
  }
  // sobrancelhas
  ctx.strokeStyle = who === 'brann' ? '#c8c2b4' : hair;
  ctx.lineWidth = 2; ctx.lineCap = 'round';
  if (bo === 'angry') {
    ctx.beginPath(); ctx.moveTo(35, 52); ctx.lineTo(46, 55); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(65, 52); ctx.lineTo(54, 55); ctx.stroke();
  } else if (bo === 'sad') {
    ctx.beginPath(); ctx.moveTo(35, 54); ctx.lineTo(46, 51); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(65, 54); ctx.lineTo(54, 51); ctx.stroke();
  } else {
    ctx.beginPath(); ctx.moveTo(36, 52); ctx.lineTo(46, 53); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(64, 52); ctx.lineTo(54, 53); ctx.stroke();
  }
  // nariz
  ctx.strokeStyle = 'rgba(110,60,40,.45)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(50, 62); ctx.quadraticCurveTo(52, 66, 49, 67); ctx.stroke();
  // boca
  ctx.strokeStyle = 'rgba(120,55,50,.8)'; ctx.lineWidth = 1.6;
  ctx.beginPath();
  if (bo === 'sad') { ctx.moveTo(45, 76); ctx.quadraticCurveTo(50, 73, 55, 76); }
  else if (mood === 'smile') { ctx.moveTo(45, 73); ctx.quadraticCurveTo(50, 78, 55, 73); }
  else if (mood === 'smirk') { ctx.moveTo(45, 75); ctx.quadraticCurveTo(51, 77, 56, 72); }
  else if (bo === 'angry') { ctx.moveTo(45, 75); ctx.quadraticCurveTo(50, 73, 55, 75); }
  else { ctx.moveTo(46, 74); ctx.lineTo(54, 74); }
  ctx.stroke();
  // cicatriz / detalhes
  if (who === 'brann') {
    ctx.strokeStyle = 'rgba(120,70,60,.55)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(36, 46); ctx.lineTo(44, 66); ctx.stroke();
    ctx.fillStyle = '#2b2b30'; ctx.beginPath(); ctx.ellipse(59, 58, 4.6, 3.4, -.2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#1a1a1e'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(54, 56); ctx.lineTo(64, 60); ctx.stroke();
  }
  if (who === 'rowan' && mood !== 'smile') {
    ctx.strokeStyle = 'rgba(150,80,60,.35)'; ctx.lineWidth = .8;
    ctx.beginPath(); ctx.moveTo(61, 64); ctx.lineTo(64, 69); ctx.stroke();
  }
  if (mood === 'tears') {
    ctx.fillStyle = 'rgba(180,220,255,.75)';
    ellipse(ctx, 35, 66, 1.6, 3.2); ctx.fill();
    ellipse(ctx, 65, 66, 1.6, 3.2); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.5)'; ctx.fillRect(34.5, 65, 1, 1);
  }
  // luz lateral
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const lg = ctx.createLinearGradient(70, 0, 100, 0);
  lg.addColorStop(0, 'rgba(255,230,180,0)'); lg.addColorStop(1, 'rgba(255,230,180,.13)');
  ctx.fillStyle = lg; ctx.fillRect(0, 0, 100, 120);
  ctx.restore();
  // moldura
  ctx.restore();
  ctx.save();
  ctx.strokeStyle = 'rgba(216,181,106,.5)'; ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 2, y + 2, w - 4, h - 4);
  ctx.restore();
}

/* ---------------------------------------------------------- item icons */
function drawItemIcon(ctx, key, x, y, size = 24) {
  const s = size / 24;
  ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
  const it = ITEMS[key];
  if (it) {
    ctx.fillStyle = '#2a3446';
    rr(ctx, -7, -8, 14, 15, 4); ctx.fill();
    ctx.fillStyle = it.color;
    ctx.fillRect(-5, -2, 10, 8);
    ctx.fillStyle = '#c9c2a6'; ctx.fillRect(-3, -10, 6, 3);
    ctx.fillStyle = '#6b4f38'; ctx.fillRect(-2.5, -12, 5, 2);
    ctx.fillStyle = 'rgba(255,255,255,.35)'; ctx.fillRect(-4, 0, 2, 5);
    ctx.strokeStyle = 'rgba(240,230,200,.55)'; ctx.lineWidth = 1; rr(ctx, -7, -8, 14, 15, 4); ctx.stroke();
  }
  ctx.restore();
}

/* =========================================================================
   AURORA PARTIDA — characters, portraits helpers, enemy sprites
   ========================================================================= */
'use strict';

function drawHumanoid(ctx, cx, baseY, lookRef, dir, walk, scale, opts = {}) {
  const look = typeof lookRef === 'string' ? (LOOKS[lookRef] || LOOKS.rowan) : lookRef;
  const t = opts.t || 0;
  const facingUp = dir === 'up';
  const side = dir === 'left' || dir === 'right';
  const mirror = dir === 'left';
  const s = (scale || 1) * (look.small ? .8 : 1) * (look.big ? 1.16 : 1);
  const seed = opts.seed || 0;
  const step = Math.sin(walk || 0);
  const bob = Math.sin(t * 2.4 + seed) * .55;
  const capeSway = Math.sin(t * 2 + seed) * 1.6;

  ctx.save();
  ctx.translate(cx, baseY + bob);
  ctx.scale(mirror ? -s : s, s);

  // sombra
  ctx.fillStyle = 'rgba(4,7,12,.36)';
  ellipse(ctx, 0, 1, 10.5, 3.4); ctx.fill();

  // capa
  if (look.cape) {
    ctx.fillStyle = look.cape;
    ctx.beginPath();
    ctx.moveTo(-8, -25);
    ctx.quadraticCurveTo(-14 - capeSway, -14, -13 + capeSway * .4, -2);
    ctx.lineTo(-4, -4); ctx.lineTo(0, -1); ctx.lineTo(5, -5);
    ctx.quadraticCurveTo(10, -14, 8, -25); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.06)';
    ctx.beginPath(); ctx.moveTo(-8, -25); ctx.quadraticCurveTo(-11, -14, -9, -4); ctx.lineTo(-5, -5); ctx.closePath(); ctx.fill();
  }

  // arma nas costas
  if (look.weapon === 'sword') {
    ctx.save();
    ctx.rotate(-.42);
    ctx.fillStyle = '#3a2a20'; ctx.fillRect(7, -32, 3, 24);
    ctx.fillStyle = '#d8b56a'; ctx.fillRect(4.5, -35, 8, 3);
    ctx.fillStyle = '#7a5a30'; ctx.fillRect(7.5, -38, 1.8, 4);
    ctx.restore();
  }
  if (look.spear) {
    ctx.strokeStyle = '#6b5034'; ctx.lineWidth = 2.2;
    ctx.beginPath(); ctx.moveTo(10, 1); ctx.lineTo(13, -46); ctx.stroke();
    ctx.fillStyle = '#b8c0ca';
    ctx.beginPath(); ctx.moveTo(13, -53); ctx.lineTo(16, -44); ctx.lineTo(13, -46); ctx.lineTo(10, -44); ctx.closePath(); ctx.fill();
  }

  // pernas
  const legA = side ? step * 2.2 : step * 1.8;
  const legB = -legA;
  if (!look.dress && !look.robe) {
    ctx.fillStyle = look.pants;
    rr(ctx, -6 + legA * .5, -12 + Math.max(0, legA), 5, 12 - Math.max(0, legA), 1.5); ctx.fill();
    rr(ctx, 1 - legB * .5, -12 + Math.max(0, legB), 5, 12 - Math.max(0, legB), 1.5); ctx.fill();
    ctx.fillStyle = '#2a211c';
    rr(ctx, -6.5 + legA * .5, -3 + Math.max(0, legA), 6, 3, 1); ctx.fill();
    rr(ctx, .5 - legB * .5, -3 + Math.max(0, legB), 6, 3, 1); ctx.fill();
  } else {
    ctx.fillStyle = '#2b2626';
    rr(ctx, -5, -7, 4, 7, 1.5); ctx.fill();
    rr(ctx, 1, -7, 4, 7, 1.5); ctx.fill();
  }

  // vestido / manto
  if (look.dress) {
    ctx.fillStyle = look.top;
    ctx.beginPath(); ctx.moveTo(-7, -27); ctx.lineTo(7, -27);
    ctx.quadraticCurveTo(9, -17, 12, -4); ctx.quadraticCurveTo(0, 0, -12, -4);
    ctx.quadraticCurveTo(-9, -17, -7, -27); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.10)';
    ctx.beginPath(); ctx.moveTo(-5, -24); ctx.quadraticCurveTo(-7, -12, -8, -5); ctx.lineTo(-4, -6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = look.accent;
    ctx.fillRect(-7, -14, 14, 1.6);
  }
  if (look.robe) {
    ctx.fillStyle = look.top;
    ctx.beginPath(); ctx.moveTo(-8, -27); ctx.lineTo(8, -27);
    ctx.quadraticCurveTo(10, -12, 11, 0); ctx.lineTo(-11, 0);
    ctx.quadraticCurveTo(-10, -12, -8, -27); ctx.closePath(); ctx.fill();
    ctx.fillStyle = look.accent; ctx.fillRect(-8, -15, 16, 2);
  }

  // tronco
  ctx.fillStyle = look.top;
  rr(ctx, -8, -28, 16, 18, 4); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,.10)';
  rr(ctx, -6, -27, 5, 13, 2); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,.16)';
  ctx.fillRect(4, -26, 3, 15);
  if (look.apron) {
    ctx.fillStyle = '#d8c9a8'; ctx.fillRect(-6, -20, 12, 14);
    ctx.fillStyle = 'rgba(120,90,60,.3)'; ctx.fillRect(-6, -20, 12, 2);
  }
  if (look.armor) {
    ctx.fillStyle = look.accent;
    rr(ctx, -8.5, -27, 17, 8, 3); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.18)'; ctx.fillRect(-5, -26, 6, 2);
    ctx.fillStyle = 'rgba(0,0,0,.22)'; ctx.fillRect(-7, -20, 14, 2);
    if (look.pauldron) {
      ctx.fillStyle = look.accent; circle(ctx, -8, -25, 3.4); ctx.fill(); circle(ctx, 8, -25, 3.4); ctx.fill();
    }
  }
  // cinto
  ctx.fillStyle = look.accent;
  ctx.fillRect(-8, -13, 16, 2.4);
  ctx.fillStyle = '#d8b56a'; ctx.fillRect(-1.4, -13.4, 2.8, 3);

  // braços
  const armSwing = side ? -step * 2.5 : step * 2;
  ctx.fillStyle = look.armor ? look.accent : look.top;
  rr(ctx, -10.5, -25 - armSwing * .2, 4, 11, 2); ctx.fill();
  rr(ctx, 6.5, -25 + armSwing * .2, 4, 11, 2); ctx.fill();
  ctx.fillStyle = look.skin;
  circle(ctx, -8.5, -13.8 - armSwing * .2, 2.2); ctx.fill();
  circle(ctx, 8.5, -13.8 + armSwing * .2, 2.2); ctx.fill();
  if (look.pauldron) {
    ctx.fillStyle = look.accent;
    circle(ctx, -9, -26, 4.2); ctx.fill(); circle(ctx, 9, -26, 4.2); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.22)'; circle(ctx, -10, -27.5, 1.5); ctx.fill(); circle(ctx, 8, -27.5, 1.5); ctx.fill();
  }
  // cachecol
  if (look.scarf) {
    ctx.fillStyle = look.scarf;
    ctx.fillRect(-7.5, -29.5, 15, 3.4);
    ctx.beginPath(); ctx.moveTo(5, -28); ctx.quadraticCurveTo(10 + capeSway * .6, -24, 8 + capeSway, -18);
    ctx.lineTo(5.5, -19); ctx.quadraticCurveTo(7, -23, 3.5, -27); ctx.closePath(); ctx.fill();
  }

  // cabeça
  const headY = -34.5;
  ctx.fillStyle = look.skin;
  circle(ctx, 0, headY, 8.6); ctx.fill();
  if (side) { circle(ctx, -2.5, headY + 5, 1.6); ctx.fill(); }
  ctx.fillStyle = 'rgba(90,40,20,.10)';
  ellipse(ctx, 0, headY + 4.4, 7, 4); ctx.fill();

  // cabelo
  const hairStyle = look.style;
  ctx.fillStyle = look.hair;
  if (hairStyle !== 'bald' && hairStyle !== 'helmet') {
    if (facingUp) {
      circle(ctx, 0, headY - .5, 8.7); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.10)'; circle(ctx, -3, headY - 4, 3.4); ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(-8.6, headY + 1);
      ctx.quadraticCurveTo(-9, headY - 10, 0, headY - 10.5);
      ctx.quadraticCurveTo(9, headY - 10, 8.6, headY + 1);
      ctx.quadraticCurveTo(4, headY - 3.6, 1.5, headY - 5.5);
      ctx.quadraticCurveTo(-2, headY - 2, -5, headY - 4);
      ctx.quadraticCurveTo(-7, headY - 2, -8.6, headY + 1);
      ctx.closePath(); ctx.fill();
      if (hairStyle === 'long') {
        ctx.beginPath(); ctx.moveTo(-8, headY);
        ctx.quadraticCurveTo(-12, headY + 8, -9, headY + 13); ctx.lineTo(-5, headY + 11);
        ctx.quadraticCurveTo(-7, headY + 5, -6, headY); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(8, headY);
        ctx.quadraticCurveTo(12, headY + 8, 9, headY + 13); ctx.lineTo(5, headY + 11);
        ctx.quadraticCurveTo(7, headY + 5, 6, headY); ctx.closePath(); ctx.fill();
      }
    }
  }
  if (hairStyle === 'beard') {
    ctx.fillStyle = look.hair;
    ctx.beginPath(); ctx.moveTo(-7, headY + 4);
    ctx.quadraticCurveTo(-5, headY + 12, 0, headY + 12);
    ctx.quadraticCurveTo(5, headY + 12, 7, headY + 4);
    ctx.quadraticCurveTo(3, headY + 7, 0, headY + 6);
    ctx.quadraticCurveTo(-3, headY + 7, -7, headY + 4); ctx.closePath(); ctx.fill();
  }
  if (hairStyle === 'helmet') {
    ctx.fillStyle = '#77818e';
    ctx.beginPath(); ctx.arc(0, headY - .5, 8.8, Math.PI, 0); ctx.lineTo(8.8, headY + 3);
    ctx.lineTo(5, headY + 5); ctx.lineTo(-5, headY + 5); ctx.lineTo(-8.8, headY + 3); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#4d5661'; ctx.fillRect(-1.6, headY - 4, 3.2, 8);
    ctx.fillStyle = 'rgba(255,255,255,.18)'; ctx.fillRect(-7, headY - 6, 5, 2);
  }
  // rosto
  if (!facingUp) {
    const eo = side ? 2 : 0;
    ctx.fillStyle = '#221a16';
    if (side) {
      ctx.fillRect(2.4, headY - .4, 1.8, 2.2);
      ctx.fillStyle = 'rgba(255,255,255,.7)'; ctx.fillRect(2.6, headY - .2, .7, .8);
    } else {
      ctx.fillRect(-4.2, headY - .6, 1.9, 2.3);
      ctx.fillRect(2.3, headY - .6, 1.9, 2.3);
      ctx.fillStyle = 'rgba(255,255,255,.75)';
      ctx.fillRect(-3.9, headY - .3, .7, .8); ctx.fillRect(2.6, headY - .3, .7, .8);
    }
    ctx.strokeStyle = 'rgba(90,45,40,.7)'; ctx.lineWidth = 1;
    ctx.beginPath();
    if (look.tired) { ctx.moveTo(-3.8, headY + 4); ctx.lineTo(4, headY + 4); }
    else { ctx.moveTo(-2.2, headY + 4.2); ctx.quadraticCurveTo(.8, headY + 5.2, 3, headY + 4); }
    ctx.stroke();
    if (look.flower) {
      ctx.fillStyle = '#e8c878';
      for (let i = 0; i < 5; i++) { const a = i * Math.PI * 2 / 5; circle(ctx, 6.6 + Math.cos(a) * 2, headY - 6 + Math.sin(a) * 2, 1.3); ctx.fill(); }
    }
    if (look.crown) {
      ctx.fillStyle = '#e0bd72';
      ctx.beginPath(); ctx.moveTo(-7, headY - 7); ctx.lineTo(-5.5, headY - 13); ctx.lineTo(-2, headY - 9);
      ctx.lineTo(1, headY - 14); ctx.lineTo(4, headY - 9); ctx.lineTo(7, headY - 13); ctx.lineTo(7.5, headY - 7); ctx.closePath(); ctx.fill();
    }
  }
  ctx.restore();
}

/* --------------------------------------------------------- enemy sprites */
function drawWolfEnemy(ctx, t, scale, stark = false) {
  ctx.save();
  ctx.scale(scale, scale);
  const bob = Math.sin(t * 2.2) * 1.6;
  ctx.fillStyle = 'rgba(0,0,0,.35)'; ellipse(ctx, 0, 2, 34, 8); ctx.fill();
  // cauda
  ctx.strokeStyle = stark ? '#5a5a78' : '#5a6478'; ctx.lineWidth = 8; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(26, -28 + bob); ctx.quadraticCurveTo(48, -40 + Math.sin(t * 2) * 6, 43, -14); ctx.stroke();
  ctx.strokeStyle = 'rgba(160,175,210,.25)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(28, -30 + bob); ctx.quadraticCurveTo(46, -39, 42, -18); ctx.stroke();
  // corpo
  ctx.fillStyle = stark ? '#6a6a86' : '#697489';
  ellipse(ctx, 0, -28 + bob, 27, 16); ctx.fill();
  ctx.fillStyle = stark ? '#8a8aa6' : '#8a96ac';
  ellipse(ctx, -6, -33 + bob, 18, 10); ctx.fill();
  // patas
  ctx.fillStyle = '#4a5364';
  for (const [lx, ph] of [[-16, 0], [-6, 1.5], [14, 3], [23, 4.5]]) {
    const off = Math.sin(t * 3 + ph) * 2;
    rr(ctx, lx, -16 + bob, 5, 18 + off, 2); ctx.fill();
    ctx.fillStyle = '#333b49'; rr(ctx, lx - 1, -2 + bob + off, 7, 4, 1.5); ctx.fill();
    ctx.fillStyle = '#4a5364';
  }
  // cabeça
  ctx.fillStyle = stark ? '#7a7a96' : '#768198';
  ctx.save(); ctx.translate(-25, -40 + bob); ctx.rotate(-.12);
  ellipse(ctx, 0, 0, 14, 11); ctx.fill();
  // orelhas
  ctx.fillStyle = stark ? '#5a5a78' : '#596377';
  ctx.beginPath(); ctx.moveTo(-9, -6); ctx.lineTo(-12, -18); ctx.lineTo(-2, -9); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(4, -7); ctx.lineTo(4, -19); ctx.lineTo(11, -7); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(220,140,140,.35)';
  ctx.beginPath(); ctx.moveTo(-9.5, -8); ctx.lineTo(-11, -15); ctx.lineTo(-5, -9); ctx.closePath(); ctx.fill();
  // focinho
  ctx.fillStyle = stark ? '#8a8aa6' : '#8a96ac';
  ctx.beginPath(); ctx.moveTo(-6, -2); ctx.quadraticCurveTo(-19, 1, -22, 6);
  ctx.quadraticCurveTo(-15, 11, -4, 8); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#22252e'; ellipse(ctx, -21, 5, 3.4, 2.6); ctx.fill();
  // olhos
  ctx.fillStyle = stark ? '#e0e8ff' : '#f0b458';
  ctx.shadowColor = stark ? '#a0c0ff' : '#f0a030'; ctx.shadowBlur = 6;
  ellipse(ctx, -10, -3, 3.2, 2.1); ctx.fill();
  ellipse(ctx, 1, -4, 3, 2); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#1a1410'; ctx.fillRect(-11, -4, 1.2, 2.4); ctx.fillRect(0, -5, 1.2, 2.2);
  // dentes
  ctx.fillStyle = '#e8e0d0';
  for (let i = 0; i < 3; i++) {
    const tx = -14 + i * 3.4;
    ctx.beginPath(); ctx.moveTo(tx, 8); ctx.lineTo(tx + 1.4, 12); ctx.lineTo(tx + 2.6, 8); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  // marcas
  ctx.strokeStyle = 'rgba(20,24,32,.3)'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-6, -42 + bob); ctx.lineTo(2, -36 + bob); ctx.moveTo(8, -38 + bob); ctx.lineTo(15, -31 + bob); ctx.stroke();
  if (stark) glow(ctx, 0, -32, 44, 'rgba(120,160,255,.14)', .8);
  ctx.restore();
}

function drawGuardianEnemy(ctx, t, scale) {
  ctx.save(); ctx.scale(scale, scale);
  const bob = Math.sin(t * 1.1) * 3;
  ctx.fillStyle = 'rgba(0,0,0,.4)'; ellipse(ctx, 0, 2, 44, 10); ctx.fill();
  // runas de fundo
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -55, 70, 'rgba(140,220,255,.12)', .8);
  ctx.restore();
  // pernas
  ctx.fillStyle = '#6a6252';
  rr(ctx, -25, -20, 18, 22, 3); ctx.fill();
  rr(ctx, 8, -20, 18, 22, 3); ctx.fill();
  ctx.fillStyle = '#514a3e'; ctx.fillRect(-26, -22, 20, 4); ctx.fillRect(7, -22, 20, 4);
  // torso
  ctx.fillStyle = '#7c7460';
  ctx.beginPath();
  ctx.moveTo(-28, -28 + bob); ctx.lineTo(-20, -62 + bob); ctx.lineTo(0, -70 + bob);
  ctx.lineTo(22, -60 + bob); ctx.lineTo(28, -28 + bob); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#948a72';
  ctx.beginPath(); ctx.moveTo(-22, -34 + bob); ctx.lineTo(-16, -58 + bob); ctx.lineTo(4, -64 + bob); ctx.lineTo(12, -40 + bob); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(40,34,26,.5)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-12, -58 + bob); ctx.lineTo(-6, -44 + bob); ctx.lineTo(-14, -34 + bob); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(12, -55 + bob); ctx.lineTo(8, -42 + bob); ctx.lineTo(16, -34 + bob); ctx.stroke();
  // núcleo
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -46 + bob, 25, 'rgba(120,220,255,.5)', .9);
  ctx.fillStyle = 'rgba(180,240,255,.95)'; circle(ctx, 0, -46 + bob, 6); ctx.fill();
  ctx.fillStyle = 'rgba(230,255,255,.9)'; circle(ctx, 0, -46 + bob, 2.6); ctx.fill();
  ctx.restore();
  // ombros/braços
  ctx.fillStyle = '#6a6252';
  for (const sideX of [-1, 1]) {
    const ax = sideX * 34, ay = -50 + bob + Math.sin(t * 1.6 + sideX) * 2;
    ctx.save(); ctx.translate(ax, ay);
    ctx.fillStyle = '#716956';
    ctx.beginPath(); ctx.moveTo(-8, -14); ctx.lineTo(10, -10); ctx.lineTo(12, 12); ctx.lineTo(-6, 16); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#8c8068';
    circle(ctx, 2, 4, 10); ctx.fill();
    ctx.fillStyle = '#a09680'; circle(ctx, 0, 0, 4); ctx.fill();
    ctx.strokeStyle = 'rgba(40,34,26,.45)'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(-4, -6); ctx.lineTo(4, 4); ctx.stroke();
    ctx.restore();
  }
  // cabeça
  ctx.fillStyle = '#7c7460';
  ctx.beginPath(); ctx.moveTo(-11, -66 + bob); ctx.lineTo(11, -66 + bob);
  ctx.lineTo(15, -78 + bob); ctx.lineTo(0, -86 + bob); ctx.lineTo(-15, -78 + bob); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#948a72'; ctx.fillRect(-9, -78 + bob, 18, 7);
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = 'rgba(150,235,255,.95)';
  ctx.fillRect(-7, -77 + bob, 4, 2.4); ctx.fillRect(3, -77 + bob, 4, 2.4);
  ctx.restore();
  // musgo
  ctx.fillStyle = 'rgba(80,110,70,.35)';
  ellipse(ctx, -18, -34 + bob, 8, 4); ctx.fill();
  ellipse(ctx, 20, -24 + bob, 6, 3); ctx.fill();
  ctx.restore();
}

function drawHeraldEnemy(ctx, t, scale) {
  ctx.save(); ctx.scale(scale, scale);
  const bob = Math.sin(t * 1.4) * 3;
  ctx.fillStyle = 'rgba(0,0,0,.45)'; ellipse(ctx, 0, 2, 48, 11); ctx.fill();
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -78 + bob, 100, 'rgba(150,80,220,.22)', 1);
  ctx.restore();
  // asas de vazio
  for (const sideX of [-1, 1]) {
    ctx.save(); ctx.scale(sideX, 1);
    ctx.fillStyle = 'rgba(28,16,44,.92)';
    ctx.beginPath();
    ctx.moveTo(14, -100 + bob);
    ctx.quadraticCurveTo(52, -120 + Math.sin(t) * 4, 72, -84 + bob);
    ctx.quadraticCurveTo(58, -80 + bob, 54, -64 + bob);
    ctx.quadraticCurveTo(48, -72 + bob, 40, -58 + bob);
    ctx.quadraticCurveTo(34, -74 + bob, 22, -62 + bob);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(150,100,230,.35)'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(18, -94 + bob); ctx.quadraticCurveTo(44, -104, 62, -82 + bob); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(22, -78 + bob); ctx.quadraticCurveTo(40, -84, 48, -68 + bob); ctx.stroke();
    ctx.restore();
  }
  // corpo
  ctx.fillStyle = '#241b33';
  ctx.beginPath();
  ctx.moveTo(-22, -34 + bob); ctx.lineTo(-18, -82 + bob); ctx.lineTo(0, -94 + bob);
  ctx.lineTo(20, -80 + bob); ctx.lineTo(23, -34 + bob); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#332447';
  ctx.beginPath(); ctx.moveTo(-14, -40 + bob); ctx.lineTo(-12, -76 + bob); ctx.lineTo(0, -86 + bob);
  ctx.lineTo(12, -74 + bob); ctx.lineTo(14, -40 + bob); ctx.closePath(); ctx.fill();
  // armadura dourada
  ctx.strokeStyle = '#b48ae0'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-14, -60 + bob); ctx.lineTo(0, -52 + bob); ctx.lineTo(14, -60 + bob); ctx.stroke();
  // núcleo
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  glow(ctx, 0, -62 + bob, 32, 'rgba(200,90,255,.5)', 1);
  ctx.fillStyle = 'rgba(240,180,255,.95)'; circle(ctx, 0, -62 + bob, 7); ctx.fill();
  ctx.fillStyle = '#fff'; circle(ctx, 0, -62 + bob, 2.6); ctx.fill();
  ctx.restore();
  // cabeça/coroa
  ctx.fillStyle = '#1a1326';
  ctx.beginPath(); ctx.moveTo(-11, -90 + bob); ctx.lineTo(-8, -106 + bob); ctx.lineTo(0, -98 + bob);
  ctx.lineTo(8, -106 + bob); ctx.lineTo(11, -90 + bob); ctx.closePath(); ctx.fill();
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = 'rgba(220,150,255,.95)';
  ctx.fillRect(-7, -97 + bob, 4, 2); ctx.fillRect(4, -97 + bob, 4, 2);
  ctx.restore();
  ctx.fillStyle = '#b48ae0';
  for (let i = 0; i < 5; i++) {
    const a = -1.9 + i * .55;
    ctx.save(); ctx.translate(Math.cos(a) * 18, -100 + bob + Math.sin(a) * 7); ctx.rotate(a + Math.PI / 2);
    ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(3, 4); ctx.lineTo(-3, 4); ctx.closePath(); ctx.fill(); ctx.restore();
  }
  // espada colossal
  ctx.save(); ctx.translate(-34, -66 + bob); ctx.rotate(-.45);
  ctx.fillStyle = '#22182e'; ctx.fillRect(-3, -4, 6, 58);
  ctx.strokeStyle = 'rgba(180,140,240,.75)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, -4); ctx.lineTo(0, 54); ctx.stroke();
  ctx.fillStyle = '#b48ae0'; ctx.fillRect(-7, 54, 14, 4);
  ctx.fillStyle = 'rgba(230,200,255,.9)'; circle(ctx, 0, 0, 3); ctx.fill();
  ctx.restore();
  ctx.restore();
}

function drawMace(ctx, x, y, t) {
  ctx.save(); ctx.translate(x, y);
  ctx.rotate(.3 + Math.sin(t * 1.5) * .03);
  ctx.fillStyle = '#4b3a2c'; ctx.fillRect(-2, -40, 4, 44);
  ctx.fillStyle = '#6a6c72';
  ctx.beginPath(); ctx.moveTo(0, -56); ctx.lineTo(12, -48); ctx.lineTo(10, -34); ctx.lineTo(-10, -34); ctx.lineTo(-12, -48); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#8a8c92'; ctx.fillRect(-8, -46, 16, 8);
  for (let i = 0; i < 5; i++) {
    const a = i * Math.PI * 2 / 5;
    ctx.fillStyle = '#5a5c62';
    circle(ctx, Math.cos(a) * 10, -44 + Math.sin(a) * 10, 2.4); ctx.fill();
  }
  ctx.restore();
}

function drawEnemySprite(ctx, kind, cx, baseY, scale, t, opts = {}) {
  const flip = opts.flip ? -1 : 1;
  ctx.save();
  ctx.translate(cx, baseY);
  if (flip === -1) ctx.scale(-1, 1);
  if (opts.hurt) ctx.rotate(Math.sin(t * 60) * .012);
  switch (kind) {
    case 'wolf':
      drawWolfEnemy(ctx, t, scale, opts.stark);
      break;
    case 'bandit':
      drawHumanoid(ctx, 0, 0, 'bandit', 'left', 0, scale * 1.45, { t });
      // adaga
      ctx.save(); ctx.translate(-34 * scale, -30 * scale); ctx.rotate(-.6);
      ctx.fillStyle = '#c8ccd4'; ctx.beginPath(); ctx.moveTo(0, -18); ctx.lineTo(3, 2); ctx.lineTo(-3, 2); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#6a4a30'; ctx.fillRect(-2, 2, 4, 7);
      ctx.restore();
      break;
    case 'guard':
      drawHumanoid(ctx, 0, 0, 'guard', 'left', 0, scale * 1.5, { t });
      break;
    case 'warden': {
      const wardenLook = { ...LOOKS.warden, top: '#573f35', accent: '#7c5a48' };
      drawHumanoid(ctx, 0, 0, wardenLook, 'left', 0, scale * 1.5, { t });
      drawMace(ctx, -44 * scale, -8 * scale, t);
      // chifres
      ctx.fillStyle = '#c9bfae';
      ctx.beginPath(); ctx.moveTo(-8 * scale, -80 * scale); ctx.quadraticCurveTo(-24 * scale, -96 * scale, -18 * scale, -104 * scale);
      ctx.quadraticCurveTo(-10 * scale, -94 * scale, -2 * scale, -82 * scale); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(10 * scale, -80 * scale); ctx.quadraticCurveTo(26 * scale, -94 * scale, 20 * scale, -102 * scale);
      ctx.quadraticCurveTo(12 * scale, -92 * scale, 4 * scale, -82 * scale); ctx.closePath(); ctx.fill();
      break;
    }
    case 'kael': {
      const look = { ...LOOKS.kael, top: opts.corrupt ? '#3b2340' : '#8c2f38', cape: opts.corrupt ? '#24132e' : '#6e2029' };
      drawHumanoid(ctx, 0, 0, look, 'left', 0, scale * 1.65, { t });
      // espada grande
      ctx.save(); ctx.translate(-40 * scale, -22 * scale); ctx.rotate(.25);
      ctx.fillStyle = '#d8b56a'; ctx.fillRect(-3, -70, 6, 66);
      ctx.fillStyle = 'rgba(255,240,190,.5)'; ctx.fillRect(-1, -66, 1.6, 58);
      ctx.fillStyle = '#8a6a30'; ctx.fillRect(-11, 0, 22, 5);
      ctx.fillStyle = '#5a3a24'; ctx.fillRect(-2.4, 5, 4.8, 12);
      ctx.fillStyle = '#e8cf90'; circle(ctx, 0, 16, 3); ctx.fill();
      ctx.restore();
      if (opts.corrupt) {
        ctx.save(); ctx.globalCompositeOperation = 'lighter';
        glow(ctx, 0, -70, 70, 'rgba(160,90,220,.25)', .9);
        ctx.restore();
      }
      break;
    }
    case 'guardian':
      drawGuardianEnemy(ctx, t, scale);
      break;
    case 'echo': {
      const echoLook = {
        skin: '#8fb8c8', hair: '#5a7a8a', style: 'hero', top: '#3f6a7a', pants: '#2a4a55',
        accent: '#a8e0e8', scarf: '#7ab8c8', cape: '#2e5866', weapon: 'sword'
      };
      ctx.save();
      ctx.globalAlpha = .88;
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      glow(ctx, 0, -50, 70, 'rgba(100,200,220,.2)', 1);
      ctx.restore();
      drawHumanoid(ctx, 0, 0, echoLook, 'left', 0, scale * 1.55, { t });
      ctx.restore();
      // partículas
      for (let i = 0; i < 9; i++) {
        const a = t * .6 + i * 1.7;
        const rr = 26 + (i % 4) * 11;
        ctx.fillStyle = `rgba(150,230,240,${.18 + .25 * Math.sin(t * 2 + i)})`;
        ctx.fillRect(Math.cos(a) * rr, -30 - (i * 7) % 60 + Math.sin(a * 2) * 8, 2.4, 2.4);
      }
      break;
    }
    case 'herald':
      drawHeraldEnemy(ctx, t, scale);
      break;
    default:
      drawHumanoid(ctx, 0, 0, 'guard', 'left', 0, scale * 1.4, { t });
  }
  ctx.restore();
}

/* =========================================================================
   AURORA PARTIDA — battle backdrops and scene atmosphere
   ========================================================================= */
'use strict';

function battleSky(ctx, top, mid, bottom) {
  const g = ctx.createLinearGradient(0, 0, 0, 600);
  g.addColorStop(0, top); g.addColorStop(.55, mid); g.addColorStop(1, bottom);
  ctx.fillStyle = g; ctx.fillRect(0, 0, 960, 600);
}

function drawStars(ctx, t, count, maxY = 330, seed = 1) {
  for (let i = 0; i < count; i++) {
    const x = hash(i * 4.7 + seed) * 960;
    const y = hash(i * 8.3 + seed * 2) * maxY;
    const tw = .25 + .55 * (Math.sin(t * 1.5 + i * 2.2) * .5 + .5);
    ctx.fillStyle = `rgba(220,235,255,${tw})`;
    ctx.fillRect(x, y, i % 7 === 0 ? 2 : 1.2, i % 7 === 0 ? 2 : 1.2);
  }
}

function drawPineLayer(ctx, baseY, color, spacing, scale, seed = 0) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, baseY);
  for (let x = -40; x < 1000; x += spacing) {
    const h = (44 + hash(x * .13 + seed) * 55) * scale;
    const w = (16 + hash(x * .31 + seed) * 16) * scale;
    ctx.lineTo(x, baseY - h);
    ctx.lineTo(x + w, baseY - h * .35);
    ctx.lineTo(x + w * .45, baseY - h * .34);
    ctx.lineTo(x + w * 1.3, baseY);
  }
  ctx.lineTo(1000, 600); ctx.lineTo(0, 600); ctx.closePath(); ctx.fill();
}

function drawForestBattle(ctx, t) {
  battleSky(ctx, '#0a1526', '#1b3348', '#2b3f3a');
  drawStars(ctx, t, 90, 300, 2);
  // lua
  glow(ctx, 770, 100, 110, 'rgba(220,235,255,.20)', .9);
  ctx.fillStyle = '#e8eef8'; circle(ctx, 770, 100, 38); ctx.fill();
  ctx.fillStyle = 'rgba(170,190,215,.45)'; circle(ctx, 758, 90, 7); ctx.fill(); circle(ctx, 782, 110, 5); ctx.fill(); circle(ctx, 762, 114, 3.5); ctx.fill();
  // montanhas
  ctx.fillStyle = '#131f2e';
  ctx.beginPath(); ctx.moveTo(0, 330); ctx.lineTo(140, 220); ctx.lineTo(260, 310); ctx.lineTo(420, 200); ctx.lineTo(600, 330); ctx.lineTo(760, 250); ctx.lineTo(960, 340); ctx.lineTo(960, 600); ctx.lineTo(0, 600); ctx.closePath(); ctx.fill();
  drawPineLayer(ctx, 400, '#0e1c20', 46, 1, 3);
  drawPineLayer(ctx, 430, '#12241f', 64, 1.3, 8);
  // névoa
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = `rgba(120,160,170,${.035 + i * .012})`;
    ctx.beginPath();
    ctx.ellipse(200 + i * 250 + Math.sin(t * .1 + i) * 20, 350 + i * 22, 300, 26, 0, 0, Math.PI * 2); ctx.fill();
  }
  // chão
  const gg = ctx.createLinearGradient(0, 400, 0, 600);
  gg.addColorStop(0, '#17281f'); gg.addColorStop(1, '#0d1712');
  ctx.fillStyle = gg; ctx.fillRect(0, 400, 960, 200);
  ctx.strokeStyle = 'rgba(80,120,80,.25)'; ctx.lineWidth = 1.4;
  for (let i = 0; i < 90; i++) {
    const gx = hash(i * 3.3) * 960, gy = 410 + hash(i * 7.1) * 185;
    ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx + (hash(i) - .5) * 8, gy - 8 - hash(i * 2.2) * 16); ctx.stroke();
  }
  // feixes de lua
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  const beam = ctx.createLinearGradient(740, 100, 600, 460);
  beam.addColorStop(0, 'rgba(180,215,255,.09)'); beam.addColorStop(1, 'rgba(180,215,255,0)');
  ctx.fillStyle = beam;
  ctx.beginPath(); ctx.moveTo(720, 120); ctx.lineTo(810, 120); ctx.lineTo(760, 470); ctx.lineTo(540, 470); ctx.closePath(); ctx.fill();
  ctx.restore();
  // vaga-lumes
  for (let i = 0; i < 26; i++) {
    const x = hash(i * 9.1) * 960, y = 270 + hash(i * 4.4) * 280;
    const a = .2 + .5 * (Math.sin(t * 1.6 + i) * .5 + .5);
    ctx.fillStyle = `rgba(220,230,140,${a})`;
    ctx.fillRect(x + Math.sin(t * .7 + i) * 12, y + Math.cos(t * .5 + i) * 8, 2, 2);
  }
  vignette(ctx, .55);
}

function drawDungeonBattle(ctx, t) {
  battleSky(ctx, '#0d0f14', '#171a20', '#101216');
  // parede de tijolos
  for (let y = 0; y < 430; y += 34) {
    for (let x = -(y % 68 === 0 ? 0 : 40); x < 960; x += 84) {
      ctx.fillStyle = (Math.floor(x / 84) + y / 34) % 2 ? '#21242b' : '#1d2027';
      ctx.fillRect(x + 2, y + 2, 80, 30);
      ctx.fillStyle = 'rgba(0,0,0,.18)'; ctx.fillRect(x, y + 30, 84, 4);
      ctx.fillStyle = 'rgba(255,255,255,.02)'; ctx.fillRect(x + 2, y + 2, 78, 2);
    }
  }
  // arcos
  for (const ax of [130, 830]) {
    ctx.fillStyle = '#121419';
    ctx.beginPath(); ctx.moveTo(ax - 70, 430); ctx.lineTo(ax - 70, 190);
    ctx.quadraticCurveTo(ax, 60, ax + 70, 190); ctx.lineTo(ax + 70, 430); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#2e3138'; ctx.lineWidth = 7; ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.04)'; ctx.lineWidth = 2; ctx.stroke();
  }
  // tochas
  for (const [tx, ty] of [[80, 210], [880, 210], [300, 160], [660, 160]]) {
    const fl = Math.sin(t * 8 + tx) * 3;
    ctx.fillStyle = '#3b2c20'; ctx.fillRect(tx - 2, ty, 4, 34);
    glow(ctx, tx, ty - 6, 90 + fl * 3, 'rgba(255,150,60,.24)', .9);
    ctx.fillStyle = '#ffb256';
    ctx.beginPath(); ctx.moveTo(tx - 8, ty - 2); ctx.quadraticCurveTo(tx, ty - 26 - fl, tx + 8, ty - 2); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#ffe0a0';
    ctx.beginPath(); ctx.moveTo(tx - 3, ty - 3); ctx.quadraticCurveTo(tx, ty - 16 - fl * .5, tx + 3, ty - 3); ctx.closePath(); ctx.fill();
  }
  // correntes
  ctx.strokeStyle = 'rgba(90,96,108,.35)'; ctx.lineWidth = 2;
  for (let i = 0; i < 16; i++) {
    ctx.beginPath(); ctx.arc(500 + i * 4, 120 + i * 2, 3, 0, Math.PI * 2); ctx.stroke();
  }
  // chão
  const pg = ctx.createLinearGradient(0, 410, 0, 600);
  pg.addColorStop(0, '#24262c'); pg.addColorStop(1, '#15171b');
  ctx.fillStyle = pg; ctx.fillRect(0, 410, 960, 190);
  ctx.strokeStyle = 'rgba(0,0,0,.3)'; ctx.lineWidth = 2;
  for (let i = 0; i < 6; i++) { ctx.beginPath(); ctx.moveTo(0, 425 + i * 32); ctx.lineTo(960, 425 + i * 32); ctx.stroke(); }
  for (let i = 0; i < 8; i++) { ctx.beginPath(); ctx.moveTo(i * 140, 410); ctx.lineTo(i * 140 + 40, 600); ctx.stroke(); }
  // poças refletindo
  ctx.fillStyle = 'rgba(120,160,180,.05)';
  ellipse(ctx, 250, 540, 120, 14); ctx.fill();
  ellipse(ctx, 700, 500, 90, 10); ctx.fill();
  // poeira
  for (let i = 0; i < 30; i++) {
    const x = hash(i * 5.1) * 960, y = 150 + ((t * 8 + i * 33) % 400);
    ctx.fillStyle = `rgba(200,205,215,${.04 + hash(i) * .08})`;
    ctx.fillRect(x, y, 1.5, 1.5);
  }
  vignette(ctx, .7);
}

function drawTempleBattle(ctx, t) {
  battleSky(ctx, '#050813', '#0b1226', '#131b33');
  drawStars(ctx, t, 130, 460, 7);
  // nebulosa
  const ng = ctx.createRadialGradient(640, 200, 20, 640, 200, 360);
  ng.addColorStop(0, 'rgba(90,90,190,.13)'); ng.addColorStop(1, 'rgba(90,90,190,0)');
  ctx.fillStyle = ng; ctx.fillRect(0, 0, 960, 600);
  // pilares flutuantes
  for (const [px, py, sc] of [[130, 250, 1], [830, 230, 1.1], [300, 140, .55], [700, 120, .5]]) {
    ctx.save(); ctx.translate(px, py + Math.sin(t * .5 + px) * 5); ctx.scale(sc, sc);
    ctx.fillStyle = '#2e3a52'; ctx.fillRect(-22, -110, 44, 220);
    ctx.fillStyle = '#43516e'; ctx.fillRect(-18, -106, 24, 212);
    ctx.fillStyle = 'rgba(140,220,255,.32)'; ctx.fillRect(-6, -80, 3, 70);
    ctx.fillStyle = '#232c40'; ctx.fillRect(-30, -120, 60, 12); ctx.fillRect(-30, 108, 60, 12);
    ctx.restore();
  }
  // raios de luz
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 3; i++) {
    const g = ctx.createLinearGradient(480 + i * 40, 0, 480 + i * 40, 480);
    g.addColorStop(0, 'rgba(140,220,255,.09)'); g.addColorStop(1, 'rgba(140,220,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.moveTo(400 + i * 90, 0); ctx.lineTo(440 + i * 90, 0); ctx.lineTo(560 + i * 70, 470); ctx.lineTo(300 + i * 70, 470); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  // plataforma
  ctx.fillStyle = 'rgba(0,0,0,.5)'; ellipse(ctx, 480, 540, 380, 70); ctx.fill();
  const tg = ctx.createLinearGradient(0, 420, 0, 600);
  tg.addColorStop(0, '#3d4a60'); tg.addColorStop(1, '#222c40');
  ctx.fillStyle = tg;
  ctx.beginPath(); ctx.ellipse(480, 490, 430, 105, 0, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = 'rgba(140,220,255,.22)'; ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.ellipse(480, 490, 120 + i * 70, 30 + i * 18, 0, 0, Math.PI * 2); ctx.stroke(); }
  // runas
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3 + t * .06;
    ctx.save(); ctx.translate(480 + Math.cos(a) * 250, 490 + Math.sin(a) * 62);
    ctx.globalCompositeOperation = 'lighter'; glow(ctx, 0, 0, 24, 'rgba(130,220,255,.22)', .9);
    ctx.strokeStyle = 'rgba(160,230,255,.45)'; ctx.lineWidth = 1.2; circle(ctx, 0, 0, 9); ctx.stroke();
    ctx.restore();
  }
  for (let i = 0; i < 40; i++) {
    const x = hash(i * 2.2) * 960, y = ((t * 12 + i * 41) % 500) + 60;
    ctx.fillStyle = `rgba(170,230,255,${.1 + hash(i * 3.3) * .3})`;
    ctx.fillRect(x, y, 1.6, 1.6);
  }
  vignette(ctx, .65);
}

function drawThroneBattle(ctx, t, corrupt = false) {
  // parede
  const bg = ctx.createLinearGradient(0, 0, 0, 430);
  if (corrupt) { bg.addColorStop(0, '#150d20'); bg.addColorStop(1, '#241428'); }
  else { bg.addColorStop(0, '#191322'); bg.addColorStop(1, '#2b1f2c'); }
  ctx.fillStyle = bg; ctx.fillRect(0, 0, 960, 430);
  // janelas góticas
  for (const wx of [180, 480, 780]) {
    ctx.fillStyle = '#0d0a13';
    ctx.beginPath(); ctx.moveTo(wx - 48, 330); ctx.lineTo(wx - 48, 150);
    ctx.quadraticCurveTo(wx, 70, wx + 48, 150); ctx.lineTo(wx + 48, 330); ctx.closePath(); ctx.fill();
    const gg = ctx.createLinearGradient(wx, 100, wx, 330);
    if (corrupt) { gg.addColorStop(0, '#4a2058'); gg.addColorStop(.5, '#7a2a48'); gg.addColorStop(1, '#24112c'); }
    else { gg.addColorStop(0, '#3a3a78'); gg.addColorStop(.5, '#8a5a4a'); gg.addColorStop(1, '#2a2140'); }
    ctx.fillStyle = gg;
    ctx.beginPath(); ctx.moveTo(wx - 40, 326); ctx.lineTo(wx - 40, 154);
    ctx.quadraticCurveTo(wx, 82, wx + 40, 154); ctx.lineTo(wx + 40, 326); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#120d18'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(wx, 84); ctx.lineTo(wx, 328); ctx.moveTo(wx - 40, 200); ctx.lineTo(wx + 40, 200); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,220,160,.16)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(wx - 40, 240); ctx.lineTo(wx + 40, 240); ctx.stroke();
  }
  // colunas
  for (const px of [60, 900]) {
    ctx.fillStyle = '#221a28'; ctx.fillRect(px - 34, 90, 68, 350);
    ctx.fillStyle = '#332738'; ctx.fillRect(px - 26, 90, 24, 350);
    ctx.fillStyle = '#d8b56a'; ctx.fillRect(px - 38, 86, 76, 10); ctx.fillRect(px - 38, 420, 76, 12);
  }
  // lustres
  for (const lx of [300, 660]) {
    ctx.strokeStyle = 'rgba(160,140,120,.35)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(lx, 0); ctx.lineTo(lx, 90); ctx.stroke();
    ctx.fillStyle = '#3a2c22'; ellipse(ctx, lx, 96, 46, 10); ctx.fill();
    for (let i = -2; i <= 2; i++) {
      const fx = lx + i * 18;
      glow(ctx, fx, 88, 22, corrupt ? 'rgba(180,90,240,.22)' : 'rgba(255,190,100,.24)', .9);
      ctx.fillStyle = corrupt ? '#d090ff' : '#ffd890';
      ctx.beginPath(); ctx.moveTo(fx - 3, 88); ctx.quadraticCurveTo(fx, 76 + Math.sin(t * 9 + i) * 2, fx + 3, 88); ctx.closePath(); ctx.fill();
    }
  }
  // chão
  const fg = ctx.createLinearGradient(0, 420, 0, 600);
  fg.addColorStop(0, corrupt ? '#2a1826' : '#2f2420'); fg.addColorStop(1, '#120d12');
  ctx.fillStyle = fg; ctx.fillRect(0, 420, 960, 180);
  // tapete
  ctx.fillStyle = corrupt ? '#4a1020' : '#6e2028';
  ctx.beginPath(); ctx.moveTo(400, 420); ctx.lineTo(560, 420); ctx.lineTo(720, 600); ctx.lineTo(240, 600); ctx.closePath(); ctx.fill();
  ctx.fillStyle = 'rgba(216,181,106,.5)';
  ctx.beginPath(); ctx.moveTo(410, 420); ctx.lineTo(420, 420); ctx.lineTo(280, 600); ctx.lineTo(260, 600); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(540, 420); ctx.lineTo(550, 420); ctx.lineTo(700, 600); ctx.lineTo(680, 600); ctx.closePath(); ctx.fill();
  // rachaduras corruptas
  if (corrupt) {
    ctx.strokeStyle = 'rgba(200,90,255,.35)'; ctx.lineWidth = 2;
    for (let i = 0; i < 7; i++) {
      const sx = 100 + hash(i * 5.5) * 760, sy = 60 + hash(i * 2.2) * 340;
      ctx.beginPath(); ctx.moveTo(sx, sy);
      ctx.lineTo(sx + (hash(i) - .5) * 60, sy + 30);
      ctx.lineTo(sx + (hash(i + 2) - .5) * 90, sy + 70); ctx.stroke();
    }
    for (let i = 0; i < 30; i++) {
      const x = hash(i * 3.1) * 960, y = 500 - ((t * 30 + i * 20) % 300);
      ctx.fillStyle = `rgba(220,110,80,${.2 + hash(i) * .4})`;
      ctx.fillRect(x + Math.sin(t + i) * 8, y, 2, 2);
    }
  }
  vignette(ctx, .62);
}

function vignette(ctx, strength = .5) {
  const g = ctx.createRadialGradient(480, 300, 180, 480, 300, 620);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, `rgba(0,0,0,${strength})`);
  ctx.fillStyle = g; ctx.fillRect(0, 0, 960, 600);
}

function drawBattleBackdrop(ctx, kind, t, opts = {}) {
  ctx.save();
  switch (kind) {
    case 'forest': drawForestBattle(ctx, t); break;
    case 'dungeon': drawDungeonBattle(ctx, t); break;
    case 'temple': drawTempleBattle(ctx, t); break;
    case 'throne': drawThroneBattle(ctx, t, !!opts.corrupt); break;
    case 'plains':
      battleSky(ctx, '#1d2b44', '#6a5670', '#d09a70');
      drawStars(ctx, t, 40, 200, 4);
      ctx.fillStyle = 'rgba(240,170,120,.18)'; circle(ctx, 760, 260, 90); ctx.fill();
      drawPineLayer(ctx, 390, '#2a2a38', 70, .8, 4);
      ctx.fillStyle = '#243424'; ctx.fillRect(0, 380, 960, 220);
      for (let i = 0; i < 60; i++) {
        const gx = hash(i * 3.3) * 960, gy = 400 + hash(i * 7.1) * 190;
        ctx.strokeStyle = 'rgba(120,150,90,.25)';
        ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx + 3, gy - 12); ctx.stroke();
      }
      vignette(ctx, .5);
      break;
    default: drawForestBattle(ctx, t);
  }
  ctx.restore();
}

/* ambient overlay used in the overworld */
function drawMapAmbience(ctx, theme, t, state) {
  if (theme === 'village' || theme === 'fields') {
    ctx.save();
    const g = ctx.createLinearGradient(0, 0, 0, 280);
    g.addColorStop(0, 'rgba(255,170,80,.10)'); g.addColorStop(1, 'rgba(255,170,80,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 960, 280);
    ctx.restore();
    for (let i = 0; i < 16; i++) {
      const x = hash(i * 6.1) * 960;
      const y = 120 + hash(i * 3.7) * 400 + Math.sin(t * .5 + i) * 12;
      const a = .15 + .4 * (Math.sin(t * 1.2 + i * 1.7) * .5 + .5);
      ctx.fillStyle = `rgba(235,225,150,${a})`;
      ctx.fillRect(x, y, 1.8, 1.8);
    }
  }
  if (theme === 'capital') {
    for (let i = 0; i < 14; i++) {
      const x = (hash(i * 4.1) * 1000 + t * 10 * (.3 + hash(i) * .5)) % 1000;
      const y = 100 + hash(i * 7.7) * 440 + Math.sin(t + i) * 10;
      ctx.fillStyle = `rgba(245,225,180,${.1 + hash(i) * .12})`;
      ctx.fillRect(x, y, 1.6, 1.6);
    }
  }
  if (theme === 'castle' || theme === 'temple') {
    for (let i = 0; i < 20; i++) {
      const x = hash(i * 5.3) * 960;
      const y = 100 + ((t * 7 + i * 41) % 440);
      ctx.fillStyle = theme === 'temple' ? `rgba(150,225,255,${.1 + hash(i) * .2})` : `rgba(245,215,150,${.08 + hash(i) * .12})`;
      ctx.fillRect(x, y, 1.5, 1.5);
    }
  }
  if (theme === 'prison') {
    for (let i = 0; i < 22; i++) {
      const x = hash(i * 6.3) * 960;
      const y = 80 + ((t * 5 + i * 31) % 480);
      ctx.fillStyle = `rgba(200,205,215,${.03 + hash(i) * .07})`;
      ctx.fillRect(x, y, 1.5, 1.5);
    }
  }
  if (theme === 'ruined' || theme === 'castleDark') {
    for (let i = 0; i < 26; i++) {
      const x = hash(i * 3.9) * 960 + Math.sin(t * .8 + i) * 20;
      const y = 600 - ((t * 22 + i * 47) % 600);
      ctx.fillStyle = `rgba(240,120,70,${.15 + hash(i) * .4})`;
      ctx.fillRect(x, y, 2, 2);
    }
    const g = ctx.createLinearGradient(0, 0, 0, 600);
    g.addColorStop(0, 'rgba(80,20,10,.10)'); g.addColorStop(1, 'rgba(60,10,10,.24)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 960, 600);
  }
}

