  drawText(ctx, `ATQ ${hero.atk}   DEF ${hero.def}   MAG ${hero.mag}`, tx, y + 114, { size: 9.5, color: 'rgba(235,225,205,.72)' });
  drawText(ctx, `XP ${hero.xp}/${xpNeeded(hero.level)}`, tx, y + 129, { size: 8.5, color: 'rgba(216,181,106,.6)' });
