134:       if (allPartyDead(arena)) break;
135:       await enemyAct(arena, enemy);
136:       await wait(arena.config.enemyDelay || 260);
137:     }
138:     // status
139:     for (const u of [...arena.party, ...arena.enemies]) {
140:       if (u.atkUp > 0) u.atkUp--;
141:       if (u.defUp > 0) u.defUp--;
142:       if (u.atkDown > 0) u.atkDown--;
143:     }
144:     if (allPartyDead(arena)) {
145:       const choice = await showDefeat(arena);
146:       if (choice === 'retry') { resetForRetry(arena); continue; }
147:       return 'lose';
148:     }
149:     arena.turn++;
150:     await wait(220);
151:   }
152: }
