154: function resetForRetry(arena) {
155:   const s = arena.snapshot;
156:   for (let i = 0; i < G.state.party.length; i++) {
157:     Object.assign(G.state.party[i], deepCopy(s.party[i]));
158:   }
159:   arena.party = G.state.party;
160:   G.state.items = deepCopy(s.items);
161:   arena.enemies = arena.config.enemies.map(makeEnemy);
162:   arena.turn = 1; arena.usedPhase2 = false; arena.fled = false;
163:   arena.mode = 'fight'; arena.acceptInput = false; arena.chooser = null;
164:   arena.popups = []; arena.effects = []; arena.particles = []; arena.log = [];
165:   arena.totalXp = 0; arena.totalGold = 0; arena.rewards = null;
166:   for (const h of arena.party) { h.guard = false; h.atkUp = 0; h.defUp = 0; h.atkDown = 0; }
167:   arena.announce = { title: 'DE NOVO', line: 'A aurora não desiste tão fácil.', t: 0, dur: 1.6 };
168: }
