170: function allEnemiesDead(a) { return a.enemies.every(e => e.dead || e.hp <= 0); }
171: function allPartyDead(a) { return a.party.every(h => h.hp <= 0); }
172: function livingEnemies(a) { return a.enemies.filter(e => !e.dead && e.hp > 0); }
173: function livingParty(a) { return a.party.filter(h => h.hp > 0); }
