175: /* -------------------------------------------------------------- escolhas */
176: function chooseAction(arena, hero) {
177:   return new Promise(resolve => {
178:     arena.activeHero = hero;
179:     arena.acceptInput = true;
180:     arena.chooser = {
181:       hero, resolve, mode: 'command', idx: 0, skillIdx: 0, itemIdx: 0,
182:       targetSide: 'enemy', targetIdx: 0, pending: null, prevMode: 'command', msg: ''
183:     };
184:     arena.mode = 'command';
185:   });
186: }
187: 
188: function resolveChoice(arena, action) {
189:   if (!arena.chooser) return;
190:   const r = arena.chooser.resolve;
191:   arena.chooser = null;
192:   arena.acceptInput = false;
193:   r(action);
194: }
