196: function commandOptions(arena) {
197:   return BATTLE_COMMANDS.map(c => ({
198:     ...c,
199:     disabled: c.id === 'flee' && (!arena.config.canFlee || arena.enemies.some(e => e.boss && !e.dead))
200:   }));
201: }
202: 
203: function battlePickCommand(arena, idx) {
204:   const ch = arena.chooser;
205:   if (!ch || !arena.acceptInput) return;
206:   const opts = commandOptions(arena);
207:   const cmd = opts[idx];
208:   if (!cmd) return;
209:   if (cmd.disabled) {
210:     AUDIO.sfx('error');
211:     ch.msg = cmd.id === 'flee' ? 'Não há fuga deste confronto.' : 'Indisponível.';
212:     return;
213:   }
214:   AUDIO.sfx('confirm');
215:   if (cmd.id === 'attack') {
216:     if (!livingEnemies(arena).length) return;
217:     startTargeting(arena, 'enemy', (target) => ({ kind: 'attack', actor: ch.hero, target }));
218:   } else if (cmd.id === 'skill') {
219:     ch.prevMode = 'command'; ch.mode = 'skill'; ch.skillIdx = 0;
220:   } else if (cmd.id === 'item') {
221:     ch.prevMode = 'command'; ch.mode = 'item'; ch.itemIdx = 0;
222:   } else if (cmd.id === 'guard') {
223:     resolveChoice(arena, { kind: 'guard', actor: ch.hero });
224:   } else if (cmd.id === 'flee') {
225:     resolveChoice(arena, { kind: 'flee', actor: ch.hero });
226:   }
227: }
