229: function startTargeting(arena, side, confirmFn) {
230:   const ch = arena.chooser;
231:   if (!ch) return;
232:   ch.prevMode = ch.mode;
233:   ch.mode = 'target';
234:   ch.targetSide = side;
235:   ch.targetIdx = firstAliveIndex(arena, side);
236:   ch.confirmTarget = confirmFn;
237:   AUDIO.sfx('cursor');
238: }
