245: function battlePickSkill(arena, id) {
246:   const ch = arena.chooser;
247:   if (!ch) return;
248:   const sk = SKILLS[id];
249:   if (!sk) return;
250:   if (ch.hero.mp < sk.cost) { AUDIO.sfx('error'); ch.msg = 'MP insuficiente.'; return; }
251:   AUDIO.sfx('confirm');
252:   ch.pending = { kind: 'skill', skillId: id, actor: ch.hero };
253:   if (sk.target === 'enemy') {
254:     startTargeting(arena, 'enemy', (target) => ({ ...ch.pending, target }));
255:   } else if (sk.target === 'ally') {
256:     startTargeting(arena, 'ally', (target) => ({ ...ch.pending, target }));
257:   } else {
258:     resolveChoice(arena, { ...ch.pending });
259:   }
260: }
