262: function battlePickItem(arena, key) {
263:   const ch = arena.chooser;
264:   if (!ch) return;
265:   if (!G.state.items[key]) return;
266:   AUDIO.sfx('confirm');
267:   ch.pending = { kind: 'item', itemKey: key, actor: ch.hero };
268:   startTargeting(arena, 'ally', (target) => ({ ...ch.pending, target }));
