271: function battlePickTarget(arena, index) {
272:   const ch = arena.chooser;
273:   if (!ch || ch.mode !== 'target') return;
274:   if (ch.targetSide === 'enemy') {
275:     const e = arena.enemies[index];
276:     if (!e || e.dead) return;
277:   } else {
278:     const h = arena.party[index];
279:     if (!h || h.hp <= 0) return;
280:   }
281:   ch.targetIdx = index;
282:   AUDIO.sfx('confirm');
283:   const target = ch.targetSide === 'enemy' ? arena.enemies[index] : arena.party[index];
284:   const action = ch.confirmTarget ? ch.confirmTarget(target) : null;
285:   if (action) resolveChoice(arena, action);
286: }
