288: function battleBack(arena) {
289:   const ch = arena.chooser;
290:   if (!ch) return;
291:   AUDIO.sfx('cancel');
292:   if (ch.mode === 'target') {
293:     ch.mode = ch.prevMode === 'target' ? 'command' : (ch.prevMode || 'command');
294:     ch.pending = null;
295:     ch.msg = '';
296:   } else if (ch.mode === 'skill' || ch.mode === 'item') {
297:     ch.mode = 'command';
298:     ch.pending = null;
299:     ch.msg = '';
300:   }
301: }
