303: function battleKeyboard(arena) {
304:   const ch = arena.chooser;
305:   if (!ch || !arena.acceptInput) return;
306:   const p = G.pressed;
307:   if (ch.mode === 'command') {
308:     const n = BATTLE_COMMANDS.length;
309:     if (p.left) { ch.idx = ch.idx % 2 === 1 ? ch.idx - 1 : ch.idx; AUDIO.sfx('cursor'); }
310:     if (p.right) { ch.idx = ch.idx % 2 === 0 && ch.idx + 1 < n ? ch.idx + 1 : ch.idx; AUDIO.sfx('cursor'); }
311:     if (p.up) { if (ch.idx - 2 >= 0) ch.idx -= 2; else ch.idx = Math.max(0, n - 1 - (n % 2 === 0 ? 0 : 0)); AUDIO.sfx('cursor'); }
312:     if (p.down) { if (ch.idx + 2 < n) ch.idx += 2; AUDIO.sfx('cursor'); }
313:     if (p.action) battlePickCommand(arena, ch.idx);
314:     if (p.cancel) AUDIO.sfx('cancel');
315:   } else if (ch.mode === 'skill') {
316:     const ids = [...new Set(ch.hero.skills)];
317:     if (p.up) { ch.skillIdx = (ch.skillIdx + ids.length - 1) % ids.length; AUDIO.sfx('cursor'); }
318:     if (p.down) { ch.skillIdx = (ch.skillIdx + 1) % ids.length; AUDIO.sfx('cursor'); }
319:     if (p.action) battlePickSkill(arena, ids[ch.skillIdx]);
320:     if (p.cancel) battleBack(arena);
321:   } else if (ch.mode === 'item') {
322:     const keys = Object.keys(G.state.items).filter(k => G.state.items[k] > 0);
323:     if (!keys.length) { if (p.cancel) battleBack(arena); return; }
324:     if (p.up) { ch.itemIdx = (ch.itemIdx + keys.length - 1) % keys.length; AUDIO.sfx('cursor'); }
325:     if (p.down) { ch.itemIdx = (ch.itemIdx + 1) % keys.length; AUDIO.sfx('cursor'); }
326:     if (p.action) battlePickItem(arena, keys[ch.itemIdx]);
327:     if (p.cancel) battleBack(arena);
328:   } else if (ch.mode === 'target') {
329:     const list = ch.targetSide === 'enemy' ? arena.enemies : arena.party;
330:     const alive = list.map((u, i) => ({ u, i })).filter(o => ch.targetSide === 'enemy' ? (!o.u.dead && o.u.hp > 0) : o.u.hp > 0);
331:     if (!alive.length) { battleBack(arena); return; }
332:     let pos = alive.findIndex(o => o.i === ch.targetIdx);
333:     if (pos < 0) pos = 0;
334:     if (p.left || p.up) { pos = (pos + alive.length - 1) % alive.length; AUDIO.sfx('cursor'); }
335:     if (p.right || p.down) { pos = (pos + 1) % alive.length; AUDIO.sfx('cursor'); }
336:     ch.targetIdx = alive[pos].i;
337:     if (p.action) battlePickTarget(arena, ch.targetIdx);
338:     if (p.cancel) battleBack(arena);
339:   }
340: }
