342: /* -------------------------------------------------------------- combate */
343: function calcHit(arena, attacker, target, mult, type) {
344:   const atk = type === 'mag' ? attacker.mag : attacker.atk;
345:   let buff = 1;
346:   if (attacker.atkUp > 0) buff += .3;
347:   if (attacker.atkDown > 0) buff -= .25;
348:   if (attacker.enraged) buff += .18;
349:   const raw = atk * mult * buff * (.9 + Math.random() * .2);
350:   const armor = type === 'mag' ? target.def * .4 : target.def * .55;
351:   let dmg = Math.max(1, Math.round(raw - armor));
352:   if (target.guard) dmg = Math.max(1, Math.round(dmg * .5));
353:   if (target.defUp > 0) dmg = Math.max(1, Math.round(dmg * .78));
354:   return dmg;
355: }
356: 
357: function spriteOf(arena, unit) {
358:   return [...arena.partySpritesPrefab || [], ...arena.enemySpritesPrefab || []].find(s => s.unit === unit);
359: }
