365: function addParticles(arena, x, y, color, n = 12, spread = 1) {
366:   for (let i = 0; i < n; i++) {
367:     const a = Math.random() * Math.PI * 2;
368:     const sp = (30 + Math.random() * 130) * spread;
369:     arena.particles.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30, life: .5 + Math.random() * .5, t: 0, color, size: 1.5 + Math.random() * 2.5 });
370:   }
371: }
