393: function hitUnit(arena, unit, dmg, isEnemy, sourceName) {
394:   if (unit.hp <= 0) dmg = 0;
395:   unit.hp = Math.max(0, unit.hp - dmg);
396:   unit.flashAt = arena.time;
397:   const pos = isEnemy
398:     ? (arena.enemySpritesPrefab.find(s => s.unit === unit) || { x: 690, baseY: 350 })
399:     : (arena.partySpritesPrefab.find(s => s.unit === unit) || { x: 170, baseY: 410 });
400:   popup(arena, pos.x + (isEnemy ? 0 : 10), pos.baseY - (isEnemy ? 90 * (unit.size || 1) : 70), String(dmg), isEnemy ? '#ffe7b0' : '#ff9a8a', dmg > 60);
401:   addParticles(arena, pos.x, pos.baseY - (isEnemy ? 70 * (unit.size || 1) : 50), isEnemy ? '#ffd890' : '#ff9a8a', 12);
402:   arena.shake = Math.min(18, 7 + dmg * .12);
403:   if (dmg > 0) AUDIO.sfx(dmg > 55 ? 'crit' : 'hit');
404:   if (unit.hp <= 0 && !unit.dead) {
405:     unit.dead = true;
406:     unit.deathAt = arena.time;
407:     if (isEnemy) {
408:       logBattle(arena, `${unit.name} foi derrotado.`, '#e8cf90');
409:       addParticles(arena, pos.x, pos.baseY - 60, '#d8c090', 26, 1.4);
410:       AUDIO.sfx('defeat');
411:     } else {
412:       logBattle(arena, `${unit.name} caiu.`, '#ff8a8a');
413:     }
414:   }
415: }
