417: function healUnit(arena, unit, amount, isEnemy) {
418:   const before = unit.hp;
419:   unit.hp = Math.min(unit.maxHp, unit.hp + amount);
420:   const healed = unit.hp - before;
421:   const pos = isEnemy
422:     ? (arena.enemySpritesPrefab.find(s => s.unit === unit) || { x: 690, baseY: 350 })
423:     : (arena.partySpritesPrefab.find(s => s.unit === unit) || { x: 170, baseY: 410 });
424:   popup(arena, pos.x + 8, pos.baseY - (isEnemy ? 85 : 60), '+' + healed, '#9fe8a8');
425:   addParticles(arena, pos.x, pos.baseY - 40, '#9fe8a8', 14);
426:   AUDIO.sfx('heal');
427: }
