429: async function lungeAt(arena, unit, isEnemy) {
430:   const sprites = isEnemy ? arena.enemySpritesPrefab : arena.partySpritesPrefab;
431:   const s = sprites.find(sp => sp.unit === unit);
432:   if (!s) return;
433:   s.lungeAt = arena.time;
434:   s.lungeDur = .36;
435:   s.lungeDir = isEnemy ? -1 : 1;
436:   await wait(140);
437: }
