439: function skillTargets(arena, action) {
440:   const sk = SKILLS[action.skillId];
441:   if (!sk) return [];
442:   if (sk.target === 'allEnemies') return livingEnemies(arena);
443:   if (sk.target === 'party') return livingParty(arena);
444:   if (sk.target === 'self') return [action.actor];
445:   if (sk.target === 'ally') return action.target && action.target.hp > 0 ? [action.target] : [];
446:   return action.target && !action.target.dead ? [action.target] : [];
447: }
448: 
449: async function executeAction(arena, action) {
450:   if (!action) return;
451:   const actor = action.actor;
452:   if (!actor || actor.hp <= 0) return;
453:   arena.mode = 'anim';
454:   const isHero = arena.party.includes(actor);
455:   if (action.kind === 'guard') {
456:     actor.guard = true;
457:     const pos = arena.partySpritesPrefab.find(s => s.unit === actor) || { x: 170, baseY: 410 };
458:     addEffect(arena, 'shield', pos.x, pos.baseY - 42, 'rgba(150,210,255,', { dur: .8 });
459:     logBattle(arena, `${actor.name} se protege.`, '#b8d8f0');
460:     AUDIO.sfx('guard');
461:     await wait(420);
462:     return;
463:   }
464:   if (action.kind === 'flee') {
465:     if (!arena.config.canFlee || arena.enemies.some(e => e.boss && !e.dead)) {
466:       logBattle(arena, 'Não há fuga deste confronto!', '#ffb0a0');
467:       AUDIO.sfx('error');
468:       await wait(360);
469:       return;
470:     }
471:     AUDIO.sfx('flee');
472:     logBattle(arena, 'Você tenta fugir...', '#d8d0b8');
473:     await wait(380);
474:     if (Math.random() < .62) {
475:       arena.fled = true;
476:       logBattle(arena, 'A fuga foi bem-sucedida.', '#e8cf90');
477:       arena.announce = { title: 'FUGA', line: 'A poeira esconde seus passos.', t: 0, dur: 1.2 };
478:       await wait(500);
479:     } else {
480:       logBattle(arena, 'A fuga falhou!', '#ffb0a0');
481:       await wait(320);
482:     }
483:     return;
484:   }
485:   if (action.kind === 'item') {
486:     const it = ITEMS[action.itemKey];
487:     if (!it || !G.state.items[action.itemKey]) return;
488:     G.state.items[action.itemKey]--;
489:     if (G.state.items[action.itemKey] <= 0) delete G.state.items[action.itemKey];
490:     const target = action.target && action.target.hp > 0 ? action.target : actor;
491:     if (it.full) { target.hp = target.maxHp; target.mp = target.maxMp; addEffect(arena, 'heal', 170, 360, 'rgba(160,240,180,'); }
492:     else if (it.heal) healUnit(arena, target, it.heal, false);
493:     else if (it.mp) { target.mp = Math.min(target.maxMp, target.mp + it.mp); popup(arena, 180, 330, '+' + it.mp + ' MP', '#9fc8ff'); }
494:     logBattle(arena, `${actor.name} usou ${it.name}.`, '#c8e8d0');
495:     AUDIO.sfx('heal');
496:     await wait(500);
497:     return;
498:   }
499:   if (action.kind === 'attack') {
500:     let target = action.target;
501:     if (!target || target.dead) target = livingEnemies(arena)[0];
502:     if (!target) return;
503:     await lungeAt(arena, actor, false);
504:     addEffect(arena, 'slash', arena.enemySpritesPrefab.find(s => s.unit === target)?.x || 690, 280, 'rgba(255,240,200,');
505:     AUDIO.sfx('slash');
506:     await wait(120);
507:     const dmg = calcHit(arena, actor, target, 1, 'phys');
508:     hitUnit(arena, target, dmg, true);
509:     logBattle(arena, `${actor.name} ataca ${target.name} — ${dmg} de dano.`, '#f0e4c8');
510:     await wait(380);
511:     return;
512:   }
513:   if (action.kind === 'skill') {
514:     const sk = SKILLS[action.skillId];
515:     if (!sk || actor.mp < sk.cost) { logBattle(arena, 'MP insuficiente.', '#ffb0a0'); await wait(250); return; }
516:     actor.mp -= sk.cost;
517:     const targets = skillTargets(arena, action);
518:     if (!targets.length) return;
519:     logBattle(arena, `${actor.name} usa ${sk.name}!`, '#ffe1a0');
520:     if (sk.type === 'heal') {
521:       const t = targets[0];
522:       const amount = Math.round(t.maxHp * (sk.heal || .4)) + Math.round(actor.mag * 1.2);
523:       addEffect(arena, 'heal', 170, 350, 'rgba(150,240,170,', { dur: .9, r: 70 });
524:       AUDIO.sfx('heal');
525:       healUnit(arena, t, amount, false);
526:       await wait(600);
527:       return;
528:     }
529:     if (sk.type === 'buffAtk' || sk.type === 'buffDef') {
530:       for (const t of targets) {
531:         if (sk.type === 'buffAtk') t.atkUp = sk.turns || 3;
532:         else t.defUp = sk.turns || 3;
533:         const pos = arena.partySpritesPrefab.find(s => s.unit === t) || { x: 180, baseY: 400 };
534:         addEffect(arena, 'buff', pos.x, pos.baseY - 45, 'rgba(255,220,130,', { dur: .9, r: 55 });
535:       }
536:       popup(arena, 180, 300, sk.type === 'buffAtk' ? 'ATQ ↑' : 'DEF ↑', '#ffe19a');
537:       AUDIO.sfx('magic');
538:       await wait(650);
539:       return;
540:     }
541:     // ataques mágicos/físicos
542:     if (sk.target === 'enemy') await lungeAt(arena, actor, false);
543:     for (const t of targets) {
544:       const pos = arena.enemySpritesPrefab.find(s => s.unit === t);
545:       if (sk.fx === 'fire') addEffect(arena, 'fire', pos ? pos.x : 690, 300, 'rgba(255,170,70,', { dur: .9, r: 80 });
546:       else if (sk.fx === 'holy') addEffect(arena, 'holy', pos ? pos.x : 690, 280, 'rgba(255,245,190,', { dur: 1.1, r: 90 });
547:       else addEffect(arena, 'burst', pos ? pos.x : 690, 300, 'rgba(255,220,120,', { dur: .7, r: 60 });
548:       const dmg = calcHit(arena, actor, t, sk.mult || 1.5, sk.type === 'mag' ? 'mag' : 'phys');
549:       hitUnit(arena, t, dmg, true);
550:       logBattle(arena, `${t.name} sofre ${dmg} de dano.`, '#ffe1a0');
551:     }
552:     AUDIO.sfx('magic');
553:     await wait(520);
554:     return;
555:   }
556: }
