558: async function enemyAct(arena, enemy) {
559:   if (enemy.dead || enemy.hp <= 0) return;
560:   const def = ENEMIES[enemy.key];
561:   const skills = def.skills || [];
562:   let sk;
563:   // evita repetir a mesma habilidade três vezes
564:   const options = skills.filter(s => s.name !== enemy.lastSkill || Math.random() < .25);
565:   let total = 0;
566:   for (const s of (options.length ? options : skills)) total += s.weight || 1;
567:   let roll = Math.random() * total;
568:   for (const s of (options.length ? options : skills)) { roll -= s.weight || 1; if (roll <= 0) { sk = s; break; } }
569:   if (!sk) sk = skills[0];
570:   if (!sk) {
571:     const target = pickPartyTarget(arena);
572:     if (!target) return;
573:     const dmg = calcHit(arena, enemy, target, 1, 'phys');
