342: function drawBattle(ctx) {
343:   const a = G.battle;
344:   if (!a) return;
345:   ctx.save();
346:   if (a.shake > .5) {
347:     ctx.translate((Math.random() - .5) * a.shake, (Math.random() - .5) * a.shake);
348:   }
349:   drawBattleBackdrop(ctx, a.config.bg, a.time, { corrupt: a.usedPhase2 });
350: 
351:   // prefabs de posição
352:   a.enemySpritesPrefab = a.enemies.map((e, i) => {
353:     const pos = enemySpritePos(a, i);
354:     return { unit: e, x: pos.x, baseY: pos.baseY, scale: (e.size || 1) * 1.28, index: i };
355:   });
356:   a.partySpritesPrefab = a.party.map((h, i) => {
357:     const pos = partySpritePos(i);
358:     return { unit: h, x: pos.x, baseY: pos.baseY, scale: 1.62, index: i };
359:   });
360: 
361:   // inimigos
362:   a.enemyHitboxes = [];
363:   for (const s of a.enemySpritesPrefab) {
364:     const e = s.unit;
365:     if (e.dead && a.time - e.deathAt > .7) continue;
366:     const deathP = e.dead ? clamp((a.time - e.deathAt) / .7, 0, 1) : 0;
367:     const lx = battleLungeOffset(s, a.time);
368:     ctx.save();
369:     if (e.dead) ctx.globalAlpha = 1 - deathP;
370:     const hurt = a.time - e.flashAt < .18;
371:     ctx.translate(lx + (hurt ? (Math.random() - .5) * 8 : 0), deathP * 22);
372:     drawEnemySprite(ctx, e.kind, s.x, s.baseY, s.scale, a.time, { stark: e.enraged, corrupt: e.key === 'kael' && a.usedPhase2, flip: false });
373:     if (hurt) {
374:       ctx.save();
375:       ctx.globalCompositeOperation = 'lighter';
376:       glow(ctx, s.x, s.baseY - 70 * s.scale, 80 * s.scale, 'rgba(255,230,190,.25)', .9);
377:       ctx.restore();
378:     }
379:     ctx.restore();
380:     if (!e.dead) {
381:       drawEnemyHpBar(ctx, e, s.x, s.baseY + 12, Math.min(150, 90 * s.scale));
382:       a.enemyHitboxes.push({ x: s.x - 70 * s.scale, y: s.baseY - 150 * s.scale, w: 140 * s.scale, h: 160 * s.scale, index: s.index });
383:     }
384:     if (a.chooser && a.chooser.mode === 'target' && a.chooser.targetSide === 'enemy' && a.chooser.targetIdx === s.index && !e.dead) {
385:       drawEnemyTargetMarker(ctx, a, s, true);
386:     }
387:   }
388: 
389:   // heróis
390:   for (const s of a.partySpritesPrefab) {
391:     const h = s.unit;
392:     const lx = battleLungeOffset(s, a.time);
393:     const hurt = a.time - h.flashAt < .18;
394:     const dead = h.hp <= 0;
395:     ctx.save();
396:     if (dead) ctx.globalAlpha = .4;
397:     ctx.translate(lx + (hurt ? (Math.random() - .5) * 7 : 0), 0);
398:     const look = h.id === 'rowan' && G.state.flags.hasBlade ? 'rowanHero' : HEROES[h.id].look;
399:     drawHumanoid(ctx, s.x, s.baseY, look, 'right', 0, s.scale, { t: a.time, seed: s.index * 2 });
400:     ctx.restore();
401:   }
402: 
403:   drawBattleEffects(ctx, a);
404:   drawBattleTop(ctx, a);
405:   drawBattlePanel(ctx, a);
406:   drawBattleAnnounce(ctx, a);
407: 
408:   if (a.mode === 'victory') drawBattleVictory(ctx, a);
409:   if (a.mode === 'defeat') drawBattleDefeat(ctx, a);
410: 
411:   if (a.flash > 0) {
412:     ctx.save(); ctx.globalAlpha = a.flash * .6;
413:     ctx.fillStyle = '#fff6e0'; ctx.fillRect(0, 0, 960, 600);
414:     ctx.restore();
415:   }
416:   ctx.restore();
417: }

