132:   note(midi, when, dur, type, gain, opts = {}) {
133:     if (!this.ctx) return;
134:     const osc = this.ctx.createOscillator();
135:     const g = this.ctx.createGain();
136:     osc.type = type;
137:     osc.frequency.value = 440 * Math.pow(2, (midi - 69) / 12);
138:     if (opts.detune) osc.detune.value = opts.detune;
139:     g.gain.setValueAtTime(0, when);
140:     g.gain.linearRampToValueAtTime(gain, when + (opts.attack || .012));
141:     g.gain.exponentialRampToValueAtTime(gain * (opts.sustain || .6), when + dur * .55);
142:     g.gain.exponentialRampToValueAtTime(.0001, when + dur);
143:     let node = osc;
144:     if (opts.filter) {
145:       const f = this.ctx.createBiquadFilter();
146:       f.type = 'lowpass';
147:       f.frequency.value = opts.filter;
148:       f.Q.value = opts.q || .7;
149:       node.connect(f); node = f;
150:     }
151:     node.connect(g);
152:     g.connect(opts.bus || this.musicGain);
153:     osc.start(when);
154:     osc.stop(when + dur + .05);
155:   }
