195:   schedule() {
196:     if (!this.ctx || !this.track) return;
197:     const t = this.track;
198:     const stepDur = 60 / t.bpm / 2;
199:     while (this.nextAt < this.ctx.currentTime + .28) {
200:       const step = this.step;
201:       const inBar = step % 8;
202:       const bar = Math.floor(step / 8) % t.chords.length;
203:       const chord = t.chords[bar];
204:       const when = this.nextAt;
205:       // pad
206:       if (t.pad && inBar === 0) {
207:         for (const n of chord) {
208:           this.note(n, when, stepDur * 7.5, 'sawtooth', .038, { filter: 850, attack: .18, sustain: .7 });
