210:         }
211:       }
212:       // baixo
213:       const bnote = t.bass[step % t.bass.length];
214:       if (bnote != null) {
215:         this.note(bnote, when, stepDur * 1.7, 'sine', .15, { attack: .01 });
216:         this.note(bnote, when, stepDur * 1.7, 'triangle', .05, { attack: .01 });
217:       }
218:       // arpejo
219:       if (t.arp) {
220:         const arpNote = chord[step % chord.length] + 12;
221:         this.note(arpNote, when, stepDur * .9, 'triangle', .035, { filter: 3000, attack: .005 });
222:       }
223:       // melodia
224:       const ln = t.lead[step % t.lead.length];
225:       if (ln != null) {
226:         this.note(ln, when, stepDur * 1.55, t.type, t.type === 'square' ? .055 : .075, { filter: t.type === 'square' ? 2400 : 4000, attack: .008 });
227:         this.note(ln + 12, when, stepDur * .9, 'sine', .022);
228:       }
229:       // percussão
230:       if (t.drums !== 'none') {
231:         if (inBar % 2 === 0) this.perc(when, 'hat', t.drums === 'battle' ? .045 : .025);
232:         if (inBar === 0 || inBar === 4) this.perc(when, 'kick', t.drums === 'battle' ? .16 : .09);
