  if (G.pressed.action) {
    const o = opts[G.title.sel];
    if (o && o.enabled) o.action();
  }
  if (G.pressed.cancel) G.title.help = true;
}

function drawTitle(ctx) {
  const t = G.title.t;
  const sky = ctx.createLinearGradient(0, 0, 0, 600);
  sky.addColorStop(0, '#070b18');
